/**
 * AuthService - Serviço Central de Autenticação da Binmax
 * 
 * Responsável por:
 * 1. Conexão oficial com endpoints /api/v1/auth e /v1/auth
 * 2. Hashing de senha seguro via Web Crypto API (SHA-256 + salt de 16 bytes)
 * 3. Persistência de sessão (token bearer, usuário, saldo de prática de US$ 10.000)
 * 4. Fallback resiliente com armazenamento local criptográfico (Zero falha se backend offline)
 * 5. Seed inicial da conta demo: demo@binmax.com / Demo@123456
 * 6. Proteção contra força bruta (bloqueio temporário após 5 tentativas)
 * 7. Recuperação de senha com tokens criptográficos válidos por 15 minutos
 */

export interface AuthUser {
  id: string;
  name: string;
  email: string;
  country: string;
  demoBalanceMinor: number;
}

export interface AuthSession {
  token: string;
  user: AuthUser;
}

export interface RegisterPayload {
  name: string;
  email: string;
  password: string;
  country?: string;
}

export interface LoginPayload {
  email: string;
  password: string;
}

export interface ResetPasswordPayload {
  token: string;
  newPassword: string;
}

interface StoredUser {
  id: string;
  name: string;
  email: string;
  passwordHash: string;
  passwordSalt: string;
  country: string;
  demoBalanceMinor: number;
  failedLoginAttempts: number;
  lockedUntil: string | null;
}

interface StoredRecoveryToken {
  token: string;
  userId: string;
  expiresAt: string;
  usedAt: string | null;
}

const STORAGE_SESSION_KEY = 'binmax_auth_session';
const STORAGE_USERS_KEY = 'binmax_auth_users_db';
const STORAGE_RECOVERY_KEY = 'binmax_auth_recovery_tokens';

// Hash e Salt via Web Crypto (Zero Math.random)
async function hashWithSalt(password: string, saltHex: string): Promise<string> {
  const enc = new TextEncoder();
  const data = enc.encode(password + saltHex);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
}

function generateRandomHex(byteCount = 16): string {
  const arr = new Uint8Array(byteCount);
  crypto.getRandomValues(arr);
  return Array.from(arr)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

export class AuthService {
  // Inicializa banco de usuários local caso não exista (com conta Demo semeada)
  private static initLocalDb(): void {
    if (typeof window === 'undefined' || !window.localStorage) return;

    try {
      const existing = window.localStorage.getItem(STORAGE_USERS_KEY);
      if (!existing) {
        const demoUser: StoredUser = {
          id: '00000000-0000-4000-8000-000000000001',
          name: 'Trader Demo Binmax',
          email: 'demo@binmax.com',
          passwordSalt: 'c7a8b9f1d2e3456789abcdef01234567',
          passwordHash: '8e8aa9233600ad27603a664119de807c118928ffdf765157b8ea0cecab3a9f5f', // Demo@123456
          country: 'ES',
          demoBalanceMinor: 1000000, // US$ 10.000,00
          failedLoginAttempts: 0,
          lockedUntil: null
        };
        window.localStorage.setItem(STORAGE_USERS_KEY, JSON.stringify([demoUser]));
      }
    } catch {
      // Ignora falhas de storage em ambientes restritos
    }
  }

  private static getLocalUsers(): StoredUser[] {
    this.initLocalDb();
    try {
      const raw = window.localStorage.getItem(STORAGE_USERS_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  }

  private static saveLocalUsers(users: StoredUser[]): void {
    try {
      window.localStorage.setItem(STORAGE_USERS_KEY, JSON.stringify(users));
    } catch {
      // ignore
    }
  }

  private static getLocalTokens(): StoredRecoveryToken[] {
    try {
      const raw = window.localStorage.getItem(STORAGE_RECOVERY_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  }

  private static saveLocalTokens(tokens: StoredRecoveryToken[]): void {
    try {
      window.localStorage.setItem(STORAGE_RECOVERY_KEY, JSON.stringify(tokens));
    } catch {
      // ignore
    }
  }

  /**
   * Registro de novo usuário
   */
  public static async register(data: RegisterPayload): Promise<AuthSession> {
    const name = data.name?.trim();
    const email = data.email?.trim().toLowerCase();
    const password = data.password;
    const country = (data.country || 'ES').toUpperCase().slice(0, 2);

    if (!name || name.length < 2) {
      throw new Error('El nombre debe tener al menos 2 caracteres');
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      throw new Error('Formato de correo electrónico inválido');
    }
    if (!password || password.length < 6) {
      throw new Error('La contraseña debe tener al menos 6 caracteres');
    }

    // 1. Tentar backend oficial via API
    try {
      const response = await fetch('/api/v1/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, email, password, country })
      });

      if (response.status === 201) {
        const result = await response.json();
        const session: AuthSession = {
          token: result.token,
          user: {
            id: result.user.id,
            name: result.user.name,
            email: result.user.email,
            country: result.user.country || country,
            demoBalanceMinor: result.user.demo_balance_minor || 1000000
          }
        };
        this.setSession(session);
        return session;
      }

      if (response.status === 409) {
        throw new Error('El correo electrónico ya está registrado');
      }

      if (response.status >= 400 && response.status < 500) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.message || 'Error en los datos de registro');
      }
    } catch (err: any) {
      // Se for erro de validação ou conflito (409), repassar
      if (err.message === 'El correo electrónico ya está registrado' || err.message?.includes('caracteres')) {
        throw err;
      }
      // Se for falha de rede/offline, continuar para motor local resiliente abaixo
    }

    // 2. Motor Resiliente Local
    const users = this.getLocalUsers();
    const existing = users.find((u) => u.email === email);
    if (existing) {
      throw new Error('El correo electrónico ya está registrado');
    }

    const salt = generateRandomHex(16);
    const hash = await hashWithSalt(password, salt);
    const id = generateRandomHex(16);

    const newUser: StoredUser = {
      id,
      name,
      email,
      passwordHash: hash,
      passwordSalt: salt,
      country,
      demoBalanceMinor: 1000000, // US$ 10.000,00 inicial
      failedLoginAttempts: 0,
      lockedUntil: null
    };

    users.push(newUser);
    this.saveLocalUsers(users);

    const session: AuthSession = {
      token: `local_session_${generateRandomHex(24)}`,
      user: {
        id: newUser.id,
        name: newUser.name,
        email: newUser.email,
        country: newUser.country,
        demoBalanceMinor: newUser.demoBalanceMinor
      }
    };

    this.setSession(session);
    return session;
  }

  /**
   * Início de Sessão (Login)
   */
  public static async login(data: LoginPayload): Promise<AuthSession> {
    const email = data.email?.trim().toLowerCase();
    const password = data.password;

    if (!email || !password) {
      throw new Error('Email y contraseña requeridos');
    }

    // 1. Tentar backend oficial via API
    try {
      const response = await fetch('/api/v1/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });

      if (response.status === 200) {
        const result = await response.json();
        const session: AuthSession = {
          token: result.token,
          user: {
            id: result.user.id,
            name: result.user.name,
            email: result.user.email,
            country: result.user.country || 'ES',
            demoBalanceMinor: result.user.demo_balance_minor || 1000000
          }
        };
        this.setSession(session);
        return session;
      }

      if (response.status === 429) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.message || 'Demasiados intentos fallidos. Cuenta bloqueada temporalmente por 15 minutos.');
      }

      if (response.status === 401) {
        throw new Error('Email o contraseña incorrectos');
      }
    } catch (err: any) {
      if (err.message === 'Email o contraseña incorrectos' || err.message?.includes('bloqueada')) {
        throw err;
      }
      // Em caso de falha de conexão, recorre ao motor local abaixo
    }

    // 2. Motor Resiliente Local
    const users = this.getLocalUsers();
    const user = users.find((u) => u.email === email);

    if (!user) {
      throw new Error('Email o contraseña incorrectos');
    }

    // Checar bloqueio temporário
    if (user.lockedUntil) {
      const lockedTime = new Date(user.lockedUntil).getTime();
      const now = Date.now();
      if (lockedTime > now) {
        const minutes = Math.ceil((lockedTime - now) / 60000);
        throw new Error(`Demasiados intentos fallidos. Cuenta bloqueada temporalmente por ${minutes} minutos.`);
      }
    }

    const testHash = await hashWithSalt(password, user.passwordSalt);
    if (testHash !== user.passwordHash) {
      user.failedLoginAttempts = (user.failedLoginAttempts || 0) + 1;
      if (user.failedLoginAttempts >= 5) {
        user.lockedUntil = new Date(Date.now() + 15 * 60 * 1000).toISOString();
        this.saveLocalUsers(users);
        throw new Error('Demasiados intentos fallidos. Cuenta bloqueada temporalmente por 15 minutos.');
      }
      this.saveLocalUsers(users);
      throw new Error('Email o contraseña incorrectos');
    }

    // Login com sucesso: zera tentativas
    user.failedLoginAttempts = 0;
    user.lockedUntil = null;
    this.saveLocalUsers(users);

    const session: AuthSession = {
      token: `local_session_${generateRandomHex(24)}`,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        country: user.country,
        demoBalanceMinor: user.demoBalanceMinor
      }
    };

    this.setSession(session);
    return session;
  }

  /**
   * Solicitação de Recuperação de Senha
   */
  public static async requestPasswordRecovery(emailInput: string): Promise<{ success: boolean; token?: string }> {
    const email = emailInput?.trim().toLowerCase();
    if (!email) {
      throw new Error('Email requerido');
    }

    // 1. Tentar backend oficial via API
    try {
      const response = await fetch('/api/v1/auth/recovery/request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email })
      });

      if (response.ok) {
        const res = await response.json();
        return { success: true, token: res.token };
      }
    } catch {
      // Fallback local
    }

    // 2. Motor Resiliente Local
    const users = this.getLocalUsers();
    const user = users.find((u) => u.email === email);
    if (!user) {
      // Sucesso uniforme para proteção de privacidade
      return { success: true };
    }

    const token = generateRandomHex(24);
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();
    const tokens = this.getLocalTokens();
    tokens.push({
      token,
      userId: user.id,
      expiresAt,
      usedAt: null
    });
    this.saveLocalTokens(tokens);

    return { success: true, token };
  }

  /**
   * Redefinição de Senha com Token
   */
  public static async resetPassword(data: ResetPasswordPayload): Promise<{ success: boolean }> {
    const token = data.token?.trim();
    const newPassword = data.newPassword;

    if (!token || !newPassword || newPassword.length < 6) {
      throw new Error('Token válido y nueva contraseña de al menos 6 caracteres requeridos');
    }

    // 1. Tentar backend oficial
    try {
      const response = await fetch('/api/v1/auth/recovery/reset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, new_password: newPassword })
      });

      if (response.ok) {
        return { success: true };
      }

      if (response.status === 400) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.message || 'El enlace de recuperación es inválido o ha expirado (límite de 15 minutos).');
      }
    } catch (err: any) {
      if (err.message?.includes('inválido') || err.message?.includes('expirado') || err.message?.includes('caracteres')) {
        throw err;
      }
    }

    // 2. Motor Resiliente Local
    const tokens = this.getLocalTokens();
    const tok = tokens.find((t) => t.token === token);
    if (!tok || tok.usedAt !== null) {
      throw new Error('El enlace de recuperación es inválido o ha expirado (límite de 15 minutos).');
    }

    if (new Date(tok.expiresAt).getTime() <= Date.now()) {
      throw new Error('El enlace de recuperación ha expirado (límite de 15 minutos).');
    }

    const users = this.getLocalUsers();
    const user = users.find((u) => u.id === tok.userId);
    if (!user) {
      throw new Error('Usuario asociado no encontrado.');
    }

    const newSalt = generateRandomHex(16);
    user.passwordSalt = newSalt;
    user.passwordHash = await hashWithSalt(newPassword, newSalt);
    user.failedLoginAttempts = 0;
    user.lockedUntil = null;
    tok.usedAt = new Date().toISOString();

    this.saveLocalUsers(users);
    this.saveLocalTokens(tokens);

    return { success: true };
  }

  /**
   * Gestão de Sessão do Usuário
   */
  public static getSession(): AuthSession | null {
    if (typeof window === 'undefined' || !window.localStorage) return null;
    try {
      const raw = window.localStorage.getItem(STORAGE_SESSION_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }

  public static setSession(session: AuthSession): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.setItem(STORAGE_SESSION_KEY, JSON.stringify(session));
    } catch {
      // ignore
    }
  }

  public static clearSession(): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.removeItem(STORAGE_SESSION_KEY);
    } catch {
      // ignore
    }
  }

  public static isAuthenticated(): boolean {
    const session = this.getSession();
    return !!(session && session.token && session.user);
  }
}

import React, { useEffect, useState, useRef } from 'react';
import type { IChartApi, ISeriesApi, UTCTimestamp } from 'lightweight-charts';
import {
  FIBONACCI_LEVELS,
  type DrawingItem,
  type DrawingToolType,
  type Point2D,
} from './drawing-types';
import { safeRandomUUID } from '../lib/uuid';

export interface ChartDrawingOverlayProps {
  chartInstance: IChartApi | null;
  activeSeries: ISeriesApi<'Candlestick'> | ISeriesApi<'Area'> | null;
  containerWidth: number;
  containerHeight: number;
  drawings: DrawingItem[];
  onAddDrawing: (drawing: DrawingItem) => void;
  onUpdateDrawing?: (drawing: DrawingItem) => void;
  onRemoveDrawing: (id: string) => void;
  activeTool: DrawingToolType;
  onFinishDrawing: () => void;
  activeColor: string;
}

interface DragState {
  drawingId: string;
  handle: 'body' | 'p1' | 'p2';
  startPrice: number;
  startLogical: number;
  initialP1: Point2D;
  initialP2?: Point2D;
}

export function ChartDrawingOverlay({
  chartInstance,
  activeSeries,
  containerWidth,
  containerHeight,
  drawings,
  onAddDrawing,
  onUpdateDrawing,
  onRemoveDrawing,
  activeTool,
  onFinishDrawing,
  activeColor,
}: ChartDrawingOverlayProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [, setRedrawKey] = useState(0);
  const [firstPoint, setFirstPoint] = useState<Point2D | null>(null);
  const [previewPoint, setPreviewPoint] = useState<Point2D | null>(null);
  const [hoveredDrawingId, setHoveredDrawingId] = useState<string | null>(null);
  const [selectedDrawingId, setSelectedDrawingId] = useState<string | null>(null);
  const [dragState, setDragState] = useState<DragState | null>(null);

  const pendingPointRef = useRef<Point2D | null>(null);
  const rafIdRef = useRef<number | null>(null);
  const dragRafRef = useRef<number | null>(null);

  // Forçar redraw do SVG em zoom/pan da escala do Lightweight Charts
  useEffect(() => {
    if (!chartInstance) return;
    const timeScale = chartInstance.timeScale();
    const handleRangeChange = () => {
      setRedrawKey((k) => k + 1);
    };
    timeScale.subscribeVisibleTimeRangeChange(handleRangeChange);
    return () => {
      timeScale.unsubscribeVisibleTimeRangeChange(handleRangeChange);
    };
  }, [chartInstance]);

  // Reset de desenho em andamento se ferramenta for cancelada
  useEffect(() => {
    if (!activeTool) {
      setFirstPoint(null);
      setPreviewPoint(null);
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
    }
  }, [activeTool]);

  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      if (dragRafRef.current !== null) {
        cancelAnimationFrame(dragRafRef.current);
        dragRafRef.current = null;
      }
    };
  }, []);

  // Manipulador de início de arraste de linha ou ponto de controle
  const handleStartDrag = (
    e: React.MouseEvent,
    drawingId: string,
    handle: 'body' | 'p1' | 'p2'
  ) => {
    if (activeTool) return;
    e.stopPropagation();
    e.preventDefault();

    const drawing = drawings.find((d) => d.id === drawingId);
    if (!drawing || !chartInstance || !activeSeries) return;

    const svgRect = svgRef.current?.getBoundingClientRect();
    if (!svgRect) return;

    const mouseX = e.clientX - svgRect.left;
    const mouseY = e.clientY - svgRect.top;

    const startPrice = activeSeries.coordinateToPrice(mouseY);
    const startLogical = chartInstance.timeScale().coordinateToLogical(mouseX);

    if (startPrice === null) return;

    setSelectedDrawingId(drawingId);
    setDragState({
      drawingId,
      handle,
      startPrice: Number(startPrice),
      startLogical: startLogical !== null ? Number(startLogical) : 0,
      initialP1: { ...drawing.p1 },
      initialP2: drawing.p2 ? { ...drawing.p2 } : undefined,
    });
  };

  // Efeito global de arraste contínuo a 60 FPS
  useEffect(() => {
    if (!dragState) return;

    const onPointerMove = (e: MouseEvent) => {
      if (!svgRef.current || !chartInstance || !activeSeries) return;

      const svgRect = svgRef.current.getBoundingClientRect();
      const currentX = e.clientX - svgRect.left;
      const currentY = e.clientY - svgRect.top;

      const currentPrice = activeSeries.coordinateToPrice(currentY);
      const currentLogical = chartInstance.timeScale().coordinateToLogical(currentX);

      if (currentPrice === null) return;

      const deltaPrice = Number(currentPrice) - dragState.startPrice;
      const deltaLogical = (currentLogical !== null ? Number(currentLogical) : 0) - dragState.startLogical;

      const drawing = drawings.find((d) => d.id === dragState.drawingId);
      if (!drawing) return;

      const updatedDrawing: DrawingItem = { ...drawing };

      if (dragState.handle === 'body') {
        if (drawing.type === 'horizontal_line') {
          // Linha horizontal translada estritamente no eixo Y (preço)
          updatedDrawing.p1 = {
            ...dragState.initialP1,
            price: Number(currentPrice),
          };
        } else if (drawing.type === 'vertical_line') {
          // Linha vertical translada estritamente no eixo X (tempo/logical)
          const newLogical = (dragState.initialP1.logical ?? 0) + deltaLogical;
          const timeScale = chartInstance.timeScale();
          const newTime = timeScale.coordinateToTime(currentX);
          updatedDrawing.p1 = {
            ...dragState.initialP1,
            logical: newLogical,
            time: (newTime ?? dragState.initialP1.time) as UTCTimestamp,
          };
        } else {
          // line, trend_line, fibonacci transladam como bloco rígido (deltaPrice + deltaLogical)
          const newP1Logical = (dragState.initialP1.logical ?? 0) + deltaLogical;
          const newP2Logical = dragState.initialP2
            ? (dragState.initialP2.logical ?? 0) + deltaLogical
            : undefined;

          updatedDrawing.p1 = {
            ...dragState.initialP1,
            price: dragState.initialP1.price + deltaPrice,
            logical: newP1Logical,
          };

          if (dragState.initialP2) {
            updatedDrawing.p2 = {
              ...dragState.initialP2,
              price: dragState.initialP2.price + deltaPrice,
              logical: newP2Logical,
            };
          }
        }
      } else if (dragState.handle === 'p1') {
        // Ajuste fino do ponto de ancoragem 1 (rotaciona/estende a linha)
        const timeScale = chartInstance.timeScale();
        const newTime = timeScale.coordinateToTime(currentX);
        updatedDrawing.p1 = {
          ...dragState.initialP1,
          price: Number(currentPrice),
          logical: currentLogical !== null ? Number(currentLogical) : dragState.initialP1.logical,
          time: (newTime ?? dragState.initialP1.time) as UTCTimestamp,
        };
      } else if (dragState.handle === 'p2' && dragState.initialP2) {
        // Ajuste fino do ponto de ancoragem 2
        const timeScale = chartInstance.timeScale();
        const newTime = timeScale.coordinateToTime(currentX);
        updatedDrawing.p2 = {
          ...dragState.initialP2,
          price: Number(currentPrice),
          logical: currentLogical !== null ? Number(currentLogical) : dragState.initialP2.logical,
          time: (newTime ?? dragState.initialP2.time) as UTCTimestamp,
        };
      }

      // Throttling rAF a 60 FPS para máxima fluidez sem lag
      if (dragRafRef.current === null) {
        dragRafRef.current = requestAnimationFrame(() => {
          onUpdateDrawing?.(updatedDrawing);
          dragRafRef.current = null;
        });
      }
    };

    const onPointerUp = () => {
      if (dragRafRef.current !== null) {
        cancelAnimationFrame(dragRafRef.current);
        dragRafRef.current = null;
      }
      setDragState(null);
    };

    window.addEventListener('mousemove', onPointerMove);
    window.addEventListener('mouseup', onPointerUp);

    return () => {
      window.removeEventListener('mousemove', onPointerMove);
      window.removeEventListener('mouseup', onPointerUp);
    };
  }, [dragState, drawings, chartInstance, activeSeries, onUpdateDrawing]);

  const getCoordinatesFromEvent = (e: React.MouseEvent<SVGSVGElement>): Point2D | null => {
    if (!chartInstance || !activeSeries) return null;
    const svgEl = e.currentTarget;
    const rect = svgEl.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const timeScale = chartInstance.timeScale();
    const logical = timeScale.coordinateToLogical(x);
    const time = timeScale.coordinateToTime(x) as UTCTimestamp | null;
    const price = activeSeries.coordinateToPrice(y);

    if (price === null) return null;

    // Se coordinateToTime retornar null (margem futura à direita ou espaço vazio),
    // preservamos o logical index exato para projeção contínua e zoom/pan
    const fallbackTime = (time ?? Math.floor(Date.now() / 1000)) as UTCTimestamp;
    return {
      time: fallbackTime,
      price: Number(price),
      logical: logical !== null ? Number(logical) : undefined,
    };
  };

  const handleSvgClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!activeTool || !chartInstance || !activeSeries) return;
    const pt = getCoordinatesFromEvent(e);
    if (!pt) return;

    if (activeTool === 'horizontal_line') {
      const newDrawing: DrawingItem = {
        id: safeRandomUUID(),
        type: 'horizontal_line',
        p1: pt,
        color: activeColor,
        lineWidth: 2,
      };
      onAddDrawing(newDrawing);
      onFinishDrawing();
      return;
    }

    if (activeTool === 'vertical_line') {
      const newDrawing: DrawingItem = {
        id: safeRandomUUID(),
        type: 'vertical_line',
        p1: pt,
        color: activeColor,
        lineWidth: 2,
      };
      onAddDrawing(newDrawing);
      onFinishDrawing();
      return;
    }

    // Ferramentas de 2 pontos (line, trend_line, fibonacci)
    if (!firstPoint) {
      setFirstPoint(pt);
      setPreviewPoint(pt);
    } else {
      const newDrawing: DrawingItem = {
        id: safeRandomUUID(),
        type: activeTool,
        p1: firstPoint,
        p2: pt,
        color: activeColor,
        lineWidth: 2,
      };
      onAddDrawing(newDrawing);
      setFirstPoint(null);
      setPreviewPoint(null);
      onFinishDrawing();
    }
  };

  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!activeTool || !firstPoint) return;
    const pt = getCoordinatesFromEvent(e);
    if (!pt) return;
    pendingPointRef.current = pt;
    if (rafIdRef.current === null) {
      rafIdRef.current = requestAnimationFrame(() => {
        if (pendingPointRef.current) {
          setPreviewPoint(pendingPointRef.current);
        }
        rafIdRef.current = null;
      });
    }
  };

  // Funções de projeção lógica -> tela
  const getPixelX = (pt: Point2D | UTCTimestamp | null | undefined): number | null => {
    if (!chartInstance || !pt) return null;
    const timeScale = chartInstance.timeScale();

    // 1. Prioridade 1: Logical index (suporta perfeitamente barras passadas, presentes E FUTURAS na margem direita)
    if (typeof pt === 'object' && 'logical' in pt && typeof pt.logical === 'number' && Number.isFinite(pt.logical)) {
      try {
        const coord = timeScale.logicalToCoordinate(Math.round(pt.logical) as any);
        if (coord !== null && Number.isFinite(Number(coord))) {
          return Number(coord);
        }
      } catch { /* ignore */ }
    }

    // 2. Prioridade 2: Conversão exata de tempo via timeToCoordinate
    const timeVal = typeof pt === 'object' && 'time' in pt ? pt.time : (typeof pt === 'number' ? pt : null);
    if (timeVal !== null) {
      try {
        const coord = timeScale.timeToCoordinate(timeVal as UTCTimestamp);
        if (coord !== null && Number.isFinite(Number(coord))) {
          return Number(coord);
        }
      } catch { /* ignore */ }
    }

    return null;
  };

  const getPixelY = (price: number): number | null => {
    if (!activeSeries || !Number.isFinite(price)) return null;
    try {
      const y = activeSeries.priceToCoordinate(price);
      return y !== null && Number.isFinite(Number(y)) ? Number(y) : null;
    } catch {
      return null;
    }
  };

  const isInteractive = Boolean(activeTool);

  return (
    <svg
      ref={svgRef}
      width={containerWidth}
      height={containerHeight}
      onClick={handleSvgClick}
      onMouseMove={handleMouseMove}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: isInteractive ? 20 : 12,
        pointerEvents: isInteractive ? 'auto' : 'none',
        cursor: activeTool ? 'crosshair' : dragState ? 'grabbing' : 'default',
      }}
    >
      {/* Desenhos Concluídos */}
      {drawings.map((d) => {
        const isTargeted = hoveredDrawingId === d.id || selectedDrawingId === d.id;

        if (d.type === 'horizontal_line') {
          const y = getPixelY(d.p1.price);
          if (y === null || y < 0 || y > containerHeight) return null;

          return (
            <g
              key={d.id}
              style={{ pointerEvents: 'auto', cursor: 'ns-resize' }}
              onClick={(e) => {
                if (activeTool) return;
                e.stopPropagation();
                setSelectedDrawingId((prev) => (prev === d.id ? null : d.id));
              }}
              onMouseEnter={() => setHoveredDrawingId(d.id)}
              onMouseLeave={() => setHoveredDrawingId(null)}
            >
              {/* Hitbox Transparente de 24px para captura e arraste vertical */}
              <line
                x1={0}
                y1={y}
                x2={containerWidth}
                y2={y}
                stroke="transparent"
                strokeWidth={24}
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'ns-resize' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {/* Traço visível */}
              <line
                x1={0}
                y1={y}
                x2={containerWidth}
                y2={y}
                stroke={d.color}
                strokeWidth={isTargeted ? d.lineWidth + 2 : d.lineWidth}
                strokeDasharray="6 3"
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'ns-resize' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {/* Preço na escala direita (arrastável) */}
              <g
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'ns-resize' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              >
                <rect
                  x={containerWidth - 78}
                  y={y - 11}
                  width={72}
                  height={22}
                  rx={4}
                  fill="#1e293b"
                  stroke={d.color}
                  strokeWidth={isTargeted ? 2 : 1}
                />
                <text
                  x={containerWidth - 42}
                  y={y + 4}
                  fill={d.color}
                  fontSize={11}
                  fontWeight={700}
                  textAnchor="middle"
                >
                  {d.p1.price.toFixed(2)}
                </text>
              </g>
              {/* Botão de Excluir Proeminente quando com hover ou selecionado */}
              {isTargeted && (
                <g
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveDrawing(d.id);
                  }}
                  style={{ cursor: 'pointer' }}
                >
                  <circle cx={42} cy={y} r={12} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
                  <text x={42} y={y + 4} fill="#fff" fontSize={12} fontWeight={900} textAnchor="middle">
                    ✕
                  </text>
                </g>
              )}
            </g>
          );
        }

        if (d.type === 'vertical_line') {
          const x = getPixelX(d.p1);
          if (x === null || x < 0 || x > containerWidth) return null;

          return (
            <g
              key={d.id}
              style={{ pointerEvents: 'auto', cursor: 'ew-resize' }}
              onClick={(e) => {
                if (activeTool) return;
                e.stopPropagation();
                setSelectedDrawingId((prev) => (prev === d.id ? null : d.id));
              }}
              onMouseEnter={() => setHoveredDrawingId(d.id)}
              onMouseLeave={() => setHoveredDrawingId(null)}
            >
              {/* Hitbox Transparente de 24px com arraste horizontal */}
              <line
                x1={x}
                y1={0}
                x2={x}
                y2={containerHeight}
                stroke="transparent"
                strokeWidth={24}
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'ew-resize' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {/* Traço visível */}
              <line
                x1={x}
                y1={0}
                x2={x}
                y2={containerHeight}
                stroke={d.color}
                strokeWidth={isTargeted ? d.lineWidth + 2 : d.lineWidth}
                strokeDasharray="6 3"
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'ew-resize' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {isTargeted && (
                <g
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveDrawing(d.id);
                  }}
                  style={{ cursor: 'pointer' }}
                >
                  <circle cx={x} cy={35} r={12} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
                  <text x={x} y={39} fill="#fff" fontSize={12} fontWeight={900} textAnchor="middle">
                    ✕
                  </text>
                </g>
              )}
            </g>
          );
        }

        if ((d.type === 'line' || d.type === 'trend_line') && d.p2) {
          const x1 = getPixelX(d.p1);
          const y1 = getPixelY(d.p1.price);
          const x2 = getPixelX(d.p2);
          const y2 = getPixelY(d.p2.price);

          if (x1 === null || y1 === null || x2 === null || y2 === null) return null;
          const midX = (x1 + x2) / 2;
          const midY = (y1 + y2) / 2;
          const dx = x2 - x1;
          const dy = y2 - y1;
          const isTrendLine = d.type === 'trend_line';

          // Projeção futura da linha de tendência (raio IQ Option)
          let extendedX = x2;
          let extendedY = y2;
          if (isTrendLine && Math.abs(dx) > 1) {
            extendedX = Math.max(containerWidth + 50, x2 + 350);
            extendedY = y1 + (dy / dx) * (extendedX - x1);
          }

          return (
            <g
              key={d.id}
              style={{ pointerEvents: 'auto', cursor: 'move' }}
              onClick={(e) => {
                if (activeTool) return;
                e.stopPropagation();
                setSelectedDrawingId((prev) => (prev === d.id ? null : d.id));
              }}
              onMouseEnter={() => setHoveredDrawingId(d.id)}
              onMouseLeave={() => setHoveredDrawingId(null)}
            >
              {/* Hitbox Transparente de 24px para arraste do corpo inteiro */}
              <line
                x1={x1}
                y1={y1}
                x2={isTrendLine && Math.abs(dx) > 1 ? extendedX : x2}
                y2={isTrendLine && Math.abs(dx) > 1 ? extendedY : y2}
                stroke="transparent"
                strokeWidth={24}
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'move' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {/* Traço visível principal */}
              <line
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={d.color}
                strokeWidth={isTargeted ? d.lineWidth + 2 : d.lineWidth}
                style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'move' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
              />
              {/* Raio projetado para o futuro em linha de tendência */}
              {isTrendLine && Math.abs(dx) > 1 && (
                <line
                  x1={x2}
                  y1={y2}
                  x2={extendedX}
                  y2={extendedY}
                  stroke={d.color}
                  strokeWidth={isTargeted ? d.lineWidth + 1 : d.lineWidth}
                  strokeDasharray="5 3"
                  strokeOpacity={0.85}
                  style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'move' }}
                  onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
                />
              )}
              {/* Pontos de controle de ancoragem arrastáveis independentes */}
              <circle
                cx={x1}
                cy={y1}
                r={isTargeted ? 7 : 4.5}
                fill={isTargeted ? '#38bdf8' : d.color}
                stroke="#0f172a"
                strokeWidth={isTargeted ? 2 : 1.5}
                style={{ cursor: 'crosshair' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'p1')}
              >
                <title>Arrastar e ajustar Ponto 1</title>
              </circle>
              <circle
                cx={x2}
                cy={y2}
                r={isTargeted ? 7 : 4.5}
                fill={isTargeted ? '#38bdf8' : d.color}
                stroke="#0f172a"
                strokeWidth={isTargeted ? 2 : 1.5}
                style={{ cursor: 'crosshair' }}
                onMouseDown={(e) => handleStartDrag(e, d.id, 'p2')}
              >
                <title>Arrastar e ajustar Ponto 2</title>
              </circle>
              {isTargeted && (
                <g
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveDrawing(d.id);
                  }}
                  style={{ cursor: 'pointer' }}
                >
                  <circle cx={midX} cy={midY} r={12} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
                  <text
                    x={midX}
                    y={midY + 4}
                    fill="#fff"
                    fontSize={12}
                    fontWeight={900}
                    textAnchor="middle"
                  >
                    ✕
                  </text>
                </g>
              )}
            </g>
          );
        }

        if (d.type === 'fibonacci' && d.p2) {
          const x1 = getPixelX(d.p1) ?? 0;
          const x2 = getPixelX(d.p2) ?? containerWidth;
          const minX = Math.min(x1, x2);
          const maxX = Math.max(containerWidth, Math.max(x1, x2) + 200);
          const diffPrice = d.p2.price - d.p1.price;

          return (
            <g
              key={d.id}
              style={{ pointerEvents: 'auto', cursor: 'move' }}
              onClick={(e) => {
                if (activeTool) return;
                e.stopPropagation();
                setSelectedDrawingId((prev) => (prev === d.id ? null : d.id));
              }}
              onMouseEnter={() => setHoveredDrawingId(d.id)}
              onMouseLeave={() => setHoveredDrawingId(null)}
            >
              {FIBONACCI_LEVELS.map((lvl) => {
                const targetPrice = d.p1.price + diffPrice * lvl.level;
                const y = getPixelY(targetPrice);
                if (y === null || y < 0 || y > containerHeight) return null;

                return (
                  <g key={lvl.level}>
                    {/* Hitbox Transparente de 24px por nível arrastável */}
                    <line
                      x1={minX}
                      y1={y}
                      x2={maxX}
                      y2={y}
                      stroke="transparent"
                      strokeWidth={24}
                      style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'move' }}
                      onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
                    />
                    <line
                      x1={minX}
                      y1={y}
                      x2={maxX}
                      y2={y}
                      stroke={lvl.color}
                      strokeWidth={isTargeted ? 2.5 : 1.5}
                      strokeDasharray="4 2"
                      style={{ cursor: dragState?.drawingId === d.id ? 'grabbing' : 'move' }}
                      onMouseDown={(e) => handleStartDrag(e, d.id, 'body')}
                    />
                    <text
                      x={minX + 8}
                      y={y - 4}
                      fill={lvl.color}
                      fontSize={10}
                      fontWeight={800}
                    >
                      {lvl.label} ({targetPrice.toFixed(2)})
                    </text>
                  </g>
                );
              })}

              {/* Pontos de controle de ancoragem arrastáveis para Fibonacci */}
              {isTargeted && (
                <>
                  <circle
                    cx={minX + 16}
                    cy={getPixelY(d.p1.price) ?? 40}
                    r={7}
                    fill="#38bdf8"
                    stroke="#0f172a"
                    strokeWidth={2}
                    style={{ cursor: 'crosshair' }}
                    onMouseDown={(e) => handleStartDrag(e, d.id, 'p1')}
                  >
                    <title>Arrastar e ajustar nível 0.0%</title>
                  </circle>
                  <circle
                    cx={minX + 16}
                    cy={getPixelY(d.p2.price) ?? 80}
                    r={7}
                    fill="#38bdf8"
                    stroke="#0f172a"
                    strokeWidth={2}
                    style={{ cursor: 'crosshair' }}
                    onMouseDown={(e) => handleStartDrag(e, d.id, 'p2')}
                  >
                    <title>Arrastar e ajustar nível 100.0%</title>
                  </circle>
                </>
              )}

              {isTargeted && (
                <g
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveDrawing(d.id);
                  }}
                  style={{ cursor: 'pointer' }}
                >
                  <circle cx={minX + 42} cy={getPixelY(d.p1.price) ?? 40} r={12} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
                  <text
                    x={minX + 42}
                    y={(getPixelY(d.p1.price) ?? 40) + 4}
                    fill="#fff"
                    fontSize={12}
                    fontWeight={900}
                    textAnchor="middle"
                  >
                    ✕
                  </text>
                </g>
              )}
            </g>
          );
        }

        return null;
      })}

      {/* Indicador Visual do Ponto 1 Ancorado */}
      {firstPoint && (
        <g pointerEvents="none">
          {(() => {
            const x1 = getPixelX(firstPoint);
            const y1 = getPixelY(firstPoint.price);
            if (x1 === null || y1 === null) return null;
            return (
              <g>
                <circle cx={x1} cy={y1} r={9} fill={activeColor} fillOpacity={0.25} />
                <circle cx={x1} cy={y1} r={4.5} fill={activeColor} stroke="#ffffff" strokeWidth={1} />
                <rect x={x1 + 10} y={y1 - 18} width={180} height={20} rx={4} fill="#0f172a" stroke={activeColor} strokeWidth={1} />
                <text x={x1 + 18} y={y1 - 5} fill="#38bdf8" fontSize={10} fontWeight={800}>
                  Ponto 1 fixado (clique o Ponto 2)
                </text>
              </g>
            );
          })()}
        </g>
      )}

      {/* Preview em Tempo Real de Linha Durante Criação */}
      {firstPoint && previewPoint && (
        <g pointerEvents="none">
          {(() => {
            const x1 = getPixelX(firstPoint);
            const y1 = getPixelY(firstPoint.price);
            const x2 = getPixelX(previewPoint);
            const y2 = getPixelY(previewPoint.price);

            if (x1 === null || y1 === null || x2 === null || y2 === null) return null;

            const dx = x2 - x1;
            const dy = y2 - y1;
            const isTrendLine = activeTool === 'trend_line';

            let extendedX = x2;
            let extendedY = y2;
            if (isTrendLine && Math.abs(dx) > 1) {
              extendedX = Math.max(containerWidth + 50, x2 + 350);
              extendedY = y1 + (dy / dx) * (extendedX - x1);
            }

            return (
              <>
                <line
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke={activeColor}
                  strokeWidth={2}
                  strokeDasharray="4 4"
                />
                {isTrendLine && Math.abs(dx) > 1 && (
                  <line
                    x1={x2}
                    y1={y2}
                    x2={extendedX}
                    y2={extendedY}
                    stroke={activeColor}
                    strokeWidth={1.5}
                    strokeDasharray="4 3"
                    strokeOpacity={0.7}
                  />
                )}
                <circle cx={x1} cy={y1} r={5} fill={activeColor} stroke="#ffffff" strokeWidth={1} />
                <circle cx={x2} cy={y2} r={5} fill={activeColor} stroke="#ffffff" strokeWidth={1} />
              </>
            );
          })()}
        </g>
      )}
    </svg>
  );
}

import React, { Component, type ErrorInfo, type ReactNode } from 'react';

export interface ChartErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode | ((reset: () => void, error: Error | null) => ReactNode);
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  onReset?: () => void;
  symbol?: string;
  autoHeal?: boolean;
  maxAutoRetries?: number;
  autoRetryDelayMs?: number;
}

interface ChartErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  autoRetriesCount?: number;
  isAutoHealing?: boolean;
}

export class ChartErrorBoundary extends Component<ChartErrorBoundaryProps, ChartErrorBoundaryState> {
  private autoHealTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(props: ChartErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      autoRetriesCount: 0,
      isAutoHealing: false,
    };
  }

  public static getDerivedStateFromError(error: Error): Partial<ChartErrorBoundaryState> {
    return {
      hasError: true,
      error,
    };
  }

  public override componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    try {
      this.setState({ errorInfo });
    } catch {
      if (this.state) {
        (this as any).state = { ...this.state, errorInfo };
      }
    }
    console.error('[ChartErrorBoundary] Falha isolada no subsistema gráfico:', error, errorInfo);
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }

    const autoHealEnabled = this.props.autoHeal ?? true;
    const maxRetries = this.props.maxAutoRetries ?? 2;
    const delay = this.props.autoRetryDelayMs ?? 600;

    const currentRetries = this.state?.autoRetriesCount ?? 0;

    if (autoHealEnabled && currentRetries < maxRetries) {
      this.setState({ isAutoHealing: true });
      if (this.state) {
        (this as any).state = { ...this.state, isAutoHealing: true };
      }
      if (this.autoHealTimer) clearTimeout(this.autoHealTimer);
      this.autoHealTimer = setTimeout(() => {
        const nextState = {
          hasError: false,
          error: null,
          errorInfo: null,
          autoRetriesCount: currentRetries + 1,
          isAutoHealing: false,
        };
        this.setState(nextState);
        (this as any).state = nextState;
        if (this.props.onReset) {
          this.props.onReset();
        }
      }, delay);
    }
  }

  public override componentWillUnmount(): void {
    if (this.autoHealTimer) {
      clearTimeout(this.autoHealTimer);
      this.autoHealTimer = null;
    }
  }

  public handleReset = (): void => {
    if (this.autoHealTimer) {
      clearTimeout(this.autoHealTimer);
      this.autoHealTimer = null;
    }
    const nextState = {
      hasError: false,
      error: null,
      errorInfo: null,
      autoRetriesCount: 0,
      isAutoHealing: false,
    };
    this.setState(nextState);
    (this as any).state = nextState;
    if (this.props.onReset) {
      this.props.onReset();
    }
  };

  public override render(): ReactNode {
    if (this.state.hasError) {
      if (typeof this.props.fallback === 'function') {
        return this.props.fallback(this.handleReset, this.state.error);
      }
      if (this.props.fallback) {
        return this.props.fallback;
      }

      const titleText = `Gráfico Temporariamente Indisponível${this.props.symbol ? ` (${this.props.symbol})` : ''}`;

      return (
        <div
          data-testid="chart-error-fallback"
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            width: '100%',
            height: '100%',
            minHeight: '260px',
            background: '#0D0F14',
            color: '#F4F5F7',
            padding: '24px',
            boxSizing: 'border-box',
            textAlign: 'center',
            border: '1px solid rgba(242, 84, 91, 0.35)',
            borderRadius: '6px',
            fontFamily: 'system-ui, -apple-system, sans-serif',
          }}
        >
          <div
            style={{
              width: '48px',
              height: '48px',
              borderRadius: '50%',
              background: 'rgba(242, 84, 91, 0.12)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '24px',
              marginBottom: '16px',
              border: '1px solid rgba(242, 84, 91, 0.3)',
            }}
          >
            📉
          </div>
          <h3
            style={{
              margin: '0 0 8px 0',
              fontSize: '15px',
              fontWeight: 700,
              color: '#F4F5F7',
              letterSpacing: '-0.01em',
            }}
          >
            {titleText}
          </h3>
          <p
            style={{
              margin: '0 0 16px 0',
              fontSize: '12px',
              lineHeight: '1.5',
              color: '#8A92A1',
              maxWidth: '380px',
            }}
          >
            Ocorreu uma falha no renderizador visual. Suas ordens ativas, histórico e saldo demo continuam
            operando com 100% de integridade no servidor.
          </p>
          {this.state.error && (
            <div
              style={{
                fontSize: '11px',
                color: '#F2545B',
                background: 'rgba(242, 84, 91, 0.08)',
                padding: '6px 12px',
                borderRadius: '4px',
                marginBottom: '16px',
                fontFamily: 'monospace',
                maxWidth: '420px',
                wordBreak: 'break-word',
              }}
            >
              {this.state.error.message || 'Erro inesperado no Canvas'}
            </div>
          )}
          {this.state.isAutoHealing && (
            <div
              data-testid="auto-healing-indicator"
              style={{
                fontSize: '11px',
                color: '#22C47A',
                marginBottom: '12px',
                fontWeight: 600,
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
              }}
            >
              <span>⚡</span> Tentando auto-recuperação transparente...
            </div>
          )}
          <button
            type="button"
            data-testid="chart-error-retry-btn"
            onClick={this.handleReset}
            style={{
              background: '#22C47A',
              color: '#070C18',
              border: 'none',
              borderRadius: '4px',
              padding: '8px 18px',
              fontSize: '12px',
              fontWeight: 700,
              cursor: 'pointer',
              transition: 'background 0.15s ease',
              display: 'flex',
              alignItems: 'center',
              gap: '6px',
            }}
            onMouseEnter={(e) => (e.currentTarget.style.background = '#2be28e')}
            onMouseLeave={(e) => (e.currentTarget.style.background = '#22C47A')}
          >
            <span>↻</span> Recarregar Gráfico
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

import React, {
  useEffect,
  useRef,
  useImperativeHandle,
  forwardRef,
  useCallback,
} from 'react';
import {
  ColorType,
  createChart,
  type AreaData,
  type CandlestickData,
  type IChartApi,
  type ISeriesApi,
  type ITimeScaleApi,
  type UTCTimestamp,
} from 'lightweight-charts';
import { isSubMinuteTimeframe, type Timeframe } from './candle-adapter';
import { ensureStrictAscendingBars } from './bar-sanitizer';
export { ensureStrictAscendingBars } from './bar-sanitizer';
import { getAssetMeta } from '../catalog/assets';

export interface IsolatedChartHostProps {
  candles: CandlestickData<UTCTimestamp>[];
  chartType: 'candles' | 'line';
  timeframe: Timeframe;
  symbol?: string;
  isBinmax?: boolean;
  onChartReady?: (api: {
    chart: IChartApi;
    activeSeries: ISeriesApi<'Candlestick'> | ISeriesApi<'Area'>;
    candleSeries: ISeriesApi<'Candlestick'>;
    areaSeries: ISeriesApi<'Area'>;
    timeScale: ITimeScaleApi<any>;
  }) => void;
  onDimensionsChange?: (dimensions: { width: number; height: number }) => void;
  className?: string;
  style?: React.CSSProperties;
}

export interface IsolatedChartHandle {
  getChart: () => IChartApi | null;
  getActiveSeries: () => ISeriesApi<'Candlestick'> | ISeriesApi<'Area'> | null;
  getCandleSeries: () => ISeriesApi<'Candlestick'> | null;
  getAreaSeries: () => ISeriesApi<'Area'> | null;
  getTimeScale: () => ITimeScaleApi<any> | null;
  scrollToRealTime: () => void;
}

/**
 * Componente Ilhado de Canvas do TradingView Lightweight Charts (v4.2.1).
 * Implementa as 4 regras de ouro de isolamento + 4 blindagens industriais:
 * 1. Instanciação ÚNICA de Chart e Séries no mount (useEffect com []);
 * 2. Atualização de velas via setData() SEM recriar ou remover séries;
 * 3. Blindagem de dimensões contra colapsos temporários (width/height <= 50);
 * 4. React.memo com comparação customizada para ignorar re-renders do shell;
 * 5. Sanitização monotônica de barras antes de setData;
 * 6. Recuperação automática de WebGL/Canvas Context Loss (GPU Reset / Sleep);
 * 7. Wake-up Auto-Resync ao retornar de abas em segundo plano.
 */
const IsolatedChartHostComponent = forwardRef<IsolatedChartHandle, IsolatedChartHostProps>(
  (
    {
      candles,
      chartType,
      timeframe,
      symbol,
      isBinmax = true,
      onChartReady,
      onDimensionsChange,
      className,
      style,
    },
    ref
  ) => {
    const hostRef = useRef<HTMLDivElement>(null);
    const chartRef = useRef<IChartApi | null>(null);
    const candleSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null);
    const areaSeriesRef = useRef<ISeriesApi<'Area'> | null>(null);
    const latestCandlesRef = useRef<CandlestickData<UTCTimestamp>[]>(candles);
    const precision = getAssetMeta(symbol ?? 'SYNTH_VOL_50').precision;
    const priceFormat = { type: 'price' as const, precision, minMove: 1 / 10 ** precision };

    latestCandlesRef.current = candles;

    const scrollToRealTime = useCallback(() => {
      chartRef.current?.timeScale().scrollToRealTime();
    }, []);

    useImperativeHandle(
      ref,
      () => ({
        getChart: () => chartRef.current,
        getActiveSeries: () =>
          chartType === 'candles' ? candleSeriesRef.current : areaSeriesRef.current,
        getCandleSeries: () => candleSeriesRef.current,
        getAreaSeries: () => areaSeriesRef.current,
        getTimeScale: () => chartRef.current?.timeScale() ?? null,
        scrollToRealTime,
      }),
      [chartType, scrollToRealTime]
    );

    // 1. Instanciação ÚNICA do gráfico e das séries no mount
    useEffect(() => {
      if (!hostRef.current) return;

      const initWidth = Math.max(hostRef.current.clientWidth || 800, 320);
      const initHeight = Math.max(hostRef.current.clientHeight || 500, 300);

      const chart = createChart(hostRef.current, {
        autoSize: false,
        width: initWidth,
        height: initHeight,
        layout: {
          background: {
            type: ColorType.Solid,
            color: isBinmax ? '#0D0F14' : 'transparent',
          },
          textColor: isBinmax ? '#8A92A1' : '#8e9ebc',
          fontSize: 11,
        },
        grid: {
          vertLines: {
            color: isBinmax ? 'rgba(244, 245, 247, 0.05)' : 'rgba(28, 41, 65, 0.45)',
          },
          horzLines: {
            color: isBinmax ? 'rgba(244, 245, 247, 0.05)' : 'rgba(28, 41, 65, 0.45)',
          },
        },
        rightPriceScale: {
          borderColor: isBinmax ? 'rgba(244, 245, 247, 0.08)' : '#1d2c48',
          scaleMargins: { top: 0.12, bottom: 0.12 },
        },
        timeScale: {
          borderColor: isBinmax ? 'rgba(244, 245, 247, 0.08)' : '#1d2c48',
          timeVisible: true,
          secondsVisible: isSubMinuteTimeframe(timeframe),
          rightOffset: 12,
          barSpacing: 10,
        },
        crosshair: {
          vertLine: { color: isBinmax ? '#8A92A1' : '#4d6994', width: 1 },
          horzLine: { color: isBinmax ? '#8A92A1' : '#4d6994', width: 1 },
        },
      });

      // Instanciação ÚNICA das séries candlestick e area
      const candleSeries = chart.addCandlestickSeries({
        upColor: isBinmax ? '#22C55E' : '#00e676',
        downColor: isBinmax ? '#E5484D' : '#ff3d71',
        borderVisible: false,
        wickUpColor: isBinmax ? '#22C55E' : '#00e676',
        wickDownColor: isBinmax ? '#E5484D' : '#ff3d71',
        lastValueVisible: false,
        priceLineVisible: false,
        visible: chartType === 'candles',
        priceFormat,
      });

      const areaSeries = chart.addAreaSeries({
        lineColor: isBinmax ? '#22C55E' : '#00e676',
        topColor: isBinmax ? 'rgba(34, 197, 94, 0.35)' : 'rgba(0, 230, 118, 0.35)',
        bottomColor: isBinmax ? 'rgba(34, 197, 94, 0.01)' : 'rgba(0, 230, 118, 0.01)',
        lineWidth: 2,
        lastValueVisible: false,
        priceLineVisible: false,
        visible: chartType === 'line',
        priceFormat,
      });

      chartRef.current = chart;
      candleSeriesRef.current = candleSeries;
      areaSeriesRef.current = areaSeries;

      // Carga inicial de dados sem destruição de série (sanitização monotônica)
      if (latestCandlesRef.current.length > 0) {
        const cleanInitial = ensureStrictAscendingBars(latestCandlesRef.current);
        if (cleanInitial.length > 0) {
          candleSeries.setData(chartType === 'candles' ? cleanInitial : []);
          const lineData: AreaData<UTCTimestamp>[] = cleanInitial.map((c) => ({
            time: c.time,
            value: c.close,
          }));
          areaSeries.setData(chartType === 'line' ? lineData : []);
        }
      }

      onDimensionsChange?.({ width: initWidth, height: initHeight });

      onChartReady?.({
        chart,
        activeSeries: chartType === 'candles' ? candleSeries : areaSeries,
        candleSeries,
        areaSeries,
        timeScale: chart.timeScale(),
      });

      // Blindagem geométrica no ResizeObserver: ignora dimensões <= 50px
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const { width, height } = entry.contentRect;
          if (width > 50 && height > 50 && chartRef.current) {
            chartRef.current.applyOptions({ width, height });
            onDimensionsChange?.({ width, height });
          }
        }
      });

      // 5. Blindagem contra perda e restauração de contexto WebGL (Khronos WebGL Spec)
      const hostEl = hostRef.current;
      resizeObserver.observe(hostEl);
      const handleContextLost = (e: Event) => {
        // Obrigatório no padrão WebGL: sem preventDefault(), o contexto é destruído permanentemente
        e.preventDefault();
        console.warn('[IsolatedChartHost] WebGL Context Lost interceptado — aguardando restauração');
      };

      const handleContextRestored = () => {
        console.info('[IsolatedChartHost] WebGL Context Restored — recuperando séries e dados');
        if (chartRef.current && latestCandlesRef.current.length > 0) {
          try {
            if (candleSeriesRef.current?.options().visible) {
              areaSeriesRef.current?.setData([]);
              candleSeriesRef.current.setData([...candleSeriesRef.current.data()]);
            } else if (areaSeriesRef.current) {
              candleSeriesRef.current?.setData([]);
              const lineData = [...areaSeriesRef.current.data()];
              areaSeriesRef.current.setData(lineData);
            }
          } catch (err) {
            console.error('[IsolatedChartHost] Falha ao recarregar dados após restauração de contexto:', err);
          }
        }
      };

      // 4. Supressão ativa de atribuição / logo do TradingView (#tv-attr-logo)
      const suppressTvLogo = () => {
        if (!hostRef.current || typeof hostRef.current.querySelector !== 'function') return;
        const logo = hostRef.current.querySelector('#tv-attr-logo, .tv-attr-logo, a[href*="tradingview.com"]');
        if (logo) {
          (logo as HTMLElement).style.display = 'none';
          (logo as HTMLElement).style.visibility = 'hidden';
          (logo as HTMLElement).style.opacity = '0';
          (logo as HTMLElement).style.pointerEvents = 'none';
        }
      };
      suppressTvLogo();
      const safeSetTimeout = typeof globalThis !== 'undefined' && typeof globalThis.setTimeout === 'function'
        ? globalThis.setTimeout
        : (typeof setTimeout === 'function' ? setTimeout : null);
      const safeClearTimeout = typeof globalThis !== 'undefined' && typeof globalThis.clearTimeout === 'function'
        ? globalThis.clearTimeout
        : (typeof clearTimeout === 'function' ? clearTimeout : null);

      const logoTimer1 = safeSetTimeout ? safeSetTimeout(suppressTvLogo, 100) : null;
      const logoTimer2 = safeSetTimeout ? safeSetTimeout(suppressTvLogo, 500) : null;

      hostEl.addEventListener('webglcontextlost', handleContextLost, false);
      hostEl.addEventListener('webglcontextrestored', handleContextRestored, false);

      return () => {
        if (logoTimer1 && safeClearTimeout) safeClearTimeout(logoTimer1);
        if (logoTimer2 && safeClearTimeout) safeClearTimeout(logoTimer2);
        hostEl.removeEventListener('webglcontextlost', handleContextLost);
        hostEl.removeEventListener('webglcontextrestored', handleContextRestored);
        resizeObserver.disconnect();
        chart.remove();
        chartRef.current = null;
        candleSeriesRef.current = null;
        areaSeriesRef.current = null;
      };
    }, []); // Dependência vazia: NUNCA reinicia o canvas no mount

    // 2. Atualização isolada de dados via setData() com blindagem monotônica
    useEffect(() => {
      if (!candleSeriesRef.current || !areaSeriesRef.current) return;

      const cleanBars = ensureStrictAscendingBars(candles);
      candleSeriesRef.current.applyOptions({ priceFormat });
      areaSeriesRef.current.applyOptions({ priceFormat });

      if (chartType === 'candles') {
        areaSeriesRef.current.setData([]);
        candleSeriesRef.current.setData(cleanBars);
      } else {
        candleSeriesRef.current.setData([]);
        const lineData: AreaData<UTCTimestamp>[] = cleanBars.map((c) => ({
          time: c.time,
          value: c.close,
        }));
        areaSeriesRef.current.setData(lineData);
      }

      // Garante autoScale recalculado com os novos limites para evitar gráficos comprimidos
      try {
        chartRef.current?.priceScale('right').applyOptions({ autoScale: true });
        chartRef.current?.timeScale().scrollToRealTime();
      } catch { /* ignore */ }
    }, [candles, chartType, symbol, timeframe]);

    // 2.1 Reset e Recálculo Forçado de AutoScale em Mudança de Símbolo (Prevenção de gráfico comprimido / fora de escala)
    useEffect(() => {
      if (!chartRef.current) return;
      try {
        chartRef.current.priceScale('right').applyOptions({
          autoScale: true,
        });
        chartRef.current.timeScale().scrollToRealTime();
      } catch {
        // defensivo
      }
    }, [symbol]);

    // 3. Comutação de visibilidade das séries sem destruição de instâncias
    useEffect(() => {
      if (!candleSeriesRef.current || !areaSeriesRef.current || !chartRef.current) return;

      const isCandles = chartType === 'candles';
      candleSeriesRef.current.applyOptions({ visible: isCandles });
      areaSeriesRef.current.applyOptions({ visible: !isCandles });

      onChartReady?.({
        chart: chartRef.current,
        activeSeries: isCandles ? candleSeriesRef.current : areaSeriesRef.current,
        candleSeries: candleSeriesRef.current,
        areaSeries: areaSeriesRef.current,
        timeScale: chartRef.current.timeScale(),
      });
    }, [chartType, onChartReady]);

    // 4. Configuração dinâmica da escala de tempo por timeframe
    useEffect(() => {
      chartRef.current?.timeScale().applyOptions({
        secondsVisible: isSubMinuteTimeframe(timeframe),
      });
    }, [timeframe]);

    // 5. Wake-up Auto-Resync na retomada de abas em segundo plano
    useEffect(() => {
      const handleVisibilityChange = () => {
        if (!document.hidden && hostRef.current && chartRef.current) {
          const w = hostRef.current.clientWidth;
          const h = hostRef.current.clientHeight;
          if (w > 50 && h > 50) {
            chartRef.current.applyOptions({ width: w, height: h });
          }
          chartRef.current.timeScale().scrollToRealTime();
        }
      };

      document.addEventListener('visibilitychange', handleVisibilityChange);
      return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
    }, []);

    return (
      <div
        ref={hostRef}
        className={`isolated-chart-host ${className ?? ''}`}
        role="img"
        aria-label="Canvas Gráfico Isolado de Trading"
        style={{
          width: '100%',
          height: '100%',
          minHeight: '350px',
          position: 'relative',
          overflow: 'hidden',
          ...style,
        }}
      />
    );
  }
);

IsolatedChartHostComponent.displayName = 'IsolatedChartHost';

export const IsolatedChartHost = React.memo(
  IsolatedChartHostComponent,
  (prev, next) => {
    return (
      prev.candles === next.candles &&
      prev.chartType === next.chartType &&
      prev.timeframe === next.timeframe &&
      prev.symbol === next.symbol &&
      prev.isBinmax === next.isBinmax
    );
  }
);

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  LineStyle,
  type AreaData,
  type CandlestickData,
  type IChartApi,
  type IPriceLine,
  type ISeriesApi,
  type UTCTimestamp,
} from 'lightweight-charts';
import { fetchHistoricalCandlesChunk, type Candle, type Contract } from '../api/client';
import type { Tick } from '../feed/protocol';
import { formatMinor, formatCurrencyBinmax } from '../lib/money';
import {
  candleData,
  candleFromTick,
  resampleCandles,
  timeframeSeconds,
  isSubMinuteTimeframe,
  type Timeframe,
} from './candle-adapter';
import { mergeObservedCandles, safeCandleFromTick } from './chart-scale-normalizer';
import { IsolatedChartHost } from './IsolatedChartHost';
