import { useEffect, useState } from 'react';
import type { IChartApi, UTCTimestamp } from 'lightweight-charts';
import { isNewTraderoomEnabled } from '../lib/feature-flags';
import { timeframeSeconds, type Timeframe } from './candle-adapter';

export interface TimeLinesOverlayProps {
  containerWidth: number;
  containerHeight: number;
  chartInstance: IChartApi | null;
  latestCandleTime: UTCTimestamp | null;
  tickTimestamp?: string | null;
  timeframe?: Timeframe;
}

export function TimeLinesOverlay({
  containerWidth,
  containerHeight,
  chartInstance,
  latestCandleTime,
  tickTimestamp,
  timeframe = '1m',
}: TimeLinesOverlayProps) {
  const isBinmax = isNewTraderoomEnabled();
  const [secondsRemaining, setSecondsRemaining] = useState<number>(60);
  const [purchaseSecondsRemaining, setPurchaseSecondsRemaining] = useState<number>(30);
  const [isPurchaseLocked, setIsPurchaseLocked] = useState<boolean>(false);

  // Sincronização temporal de alta fidelidade
  useEffect(() => {
    const updateCountdown = () => {
      const now = tickTimestamp ? Date.parse(tickTimestamp) : Date.now();
      const currentSec = Math.floor(now / 1000) % 60;

      // Contagem regressiva até a expiração (:00s do próximo minuto)
      const remExp = 60 - currentSec;
      setSecondsRemaining(remExp === 0 ? 60 : remExp);

      // Contagem regressiva até a trava de compra (:30s da vela atual)
      const remPurchase = 30 - currentSec;
      if (remPurchase > 0) {
        setPurchaseSecondsRemaining(remPurchase);
        setIsPurchaseLocked(false);
      } else {
        // Trava ativa para a vela em curso
        setPurchaseSecondsRemaining(0);
        setIsPurchaseLocked(true);
      }
    };

    updateCountdown();
    const interval = setInterval(updateCountdown, 250);
    return () => clearInterval(interval);
  }, [tickTimestamp]);

  if (containerWidth <= 0 || containerHeight <= 0) {
    return null;
  }

  // Margem da escala de preço lateral direita (~68px)
  const rightScaleWidth = 68;
  const effectiveWidth = Math.max(150, containerWidth - rightScaleWidth);

  // Obter coordenada X da vela mais recente e espaçamento de barra (barSpacing) caso disponível
  let xCandle: number | null = null;
  let barSpacing = 14;
  if (chartInstance && latestCandleTime) {
    try {
      const timeScale = chartInstance.timeScale();
      const coord = timeScale.timeToCoordinate(latestCandleTime);
      if (typeof coord === 'number' && Number.isFinite(coord)) {
        xCandle = coord;
        const logical = timeScale.coordinateToLogical(coord);
        if (logical !== null) {
          const nextX = timeScale.logicalToCoordinate(((logical as number) + 1) as any);
          if (nextX !== null && Number.isFinite(nextX) && nextX > coord) {
            barSpacing = Math.max(4, Math.min(100, nextX - coord));
          }
        }
      }
    } catch {
      xCandle = null;
    }
  }

  // Cálculo das coordenadas horizontais X geometricamente ancoradas
  let xExpiration: number;
  let xPurchase: number;

  const maxExpirationX = Math.max(80, effectiveWidth - 65);
  const tfSec = timeframe ? timeframeSeconds(timeframe) : 60;

  if (xCandle !== null && xCandle > 10 && xCandle < effectiveWidth - 20) {
    const barsAheadExp = Math.max(0.1, secondsRemaining / tfSec);
    const calculatedExpX = xCandle + barsAheadExp * barSpacing;
    xExpiration = Math.min(maxExpirationX, calculatedExpX);

    if (isPurchaseLocked || purchaseSecondsRemaining <= 0) {
      xPurchase = xCandle;
    } else {
      const barsAheadPurchase = Math.max(0.05, purchaseSecondsRemaining / tfSec);
      const calculatedPurchX = xCandle + barsAheadPurchase * barSpacing;
      const maxPurchaseX = Math.max(xCandle, xExpiration - 15);
      xPurchase = Math.max(xCandle, Math.min(maxPurchaseX, calculatedPurchX));
    }
  } else {
    // Projeção responsiva quando o gráfico não tem coordenadas visíveis
    xExpiration = Math.min(maxExpirationX, Math.round(effectiveWidth * 0.84));
    xPurchase = Math.min(xExpiration - 25, Math.round(effectiveWidth * 0.68));
  }

  const formattedSeconds = secondsRemaining.toString().padStart(2, '0');

  return (
    <div
      className="time-lines-overlay"
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: `${containerWidth}px`,
        height: `${containerHeight}px`,
        pointerEvents: 'none',
        zIndex: 5,
        overflow: 'hidden',
      }}
    >
      {/* 1. Linha Branca Pontilhada: Hora de Compra (C10) */}
      <div
        className="time-line-purchase"
        data-testid="purchase-time-line"
        style={{
          position: 'absolute',
          left: `${xPurchase}px`,
          top: 0,
          bottom: 0,
          width: '1px',
          borderLeft: isBinmax ? '1px dotted rgba(244, 245, 247, 0.85)' : '1px dashed rgba(255, 255, 255, 0.75)',
        }}
      >
        {/* Tag Superior: Hora de Compra */}
        <div
          className="time-tag-purchase"
          data-testid="time-tag-purchase"
          style={{
            position: 'absolute',
            top: isBinmax ? '24px' : '40px',
            right: isBinmax ? '8px' : undefined,
            left: isBinmax ? undefined : 0,
            transform: isBinmax ? undefined : 'translateX(-50%)',
            background: isBinmax ? 'rgba(18, 24, 38, 0.96)' : (isPurchaseLocked ? 'rgba(255, 255, 255, 0.4)' : '#ffffff'),
            border: isBinmax ? '1px solid rgba(244, 245, 247, 0.15)' : 'none',
            color: isBinmax ? '#F4F5F7' : '#080e1d',
            borderRadius: '4px',
            padding: isBinmax ? '4px 8px' : '3px 8px',
            fontSize: '10px',
            letterSpacing: '0.5px',
            whiteSpace: 'nowrap',
            boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
            display: 'flex',
            flexDirection: isBinmax ? 'column' : 'row',
            alignItems: isBinmax ? 'flex-end' : 'center',
            gap: isBinmax ? '2px' : '4px',
            fontFamily: isBinmax ? "'Geist', sans-serif" : undefined,
          }}
        >
          {isBinmax ? (
            <>
              <span style={{ fontSize: '9px', color: '#8A92A1', fontWeight: 600 }}>HORA DE COMPRA</span>
              <strong style={{ fontFamily: "'Geist Mono', monospace", fontSize: '12px', color: '#F4F5F7' }}>
                00:{purchaseSecondsRemaining.toString().padStart(2, '0')}
              </strong>
            </>
          ) : (
            <>
              <span>⏱️</span>
              <span>{isPurchaseLocked ? 'COMPRA TRAVADA' : `HORA DE COMPRA (${purchaseSecondsRemaining}s)`}</span>
            </>
          )}
        </div>

        {/* Ícone no pé da linha (C10) */}
        {isBinmax && (
          <div
            style={{
              position: 'absolute',
              bottom: '12px',
              left: 0,
              transform: 'translateX(-50%)',
              width: '18px',
              height: '18px',
              borderRadius: '50%',
              background: '#F4F5F7',
              color: '#0D0F14',
              display: 'grid',
              placeItems: 'center',
              boxShadow: '0 2px 6px rgba(0,0,0,0.6)',
            }}
            title="Hora de compra"
          >
            <svg width={10} height={10} viewBox="0 0 16 16" fill="currentColor">
              <path d="M8 0a8 8 0 1 0 8 8A8 8 0 0 0 8 0zm.5 4.5v3.25l2.5 1.5-.75 1.25L7 8.75V4.5z"/>
            </svg>
          </div>
        )}
      </div>

      {/* 2. Linha Vermelha Contínua: Expiração (C11) */}
      <div
        className="time-line-expiration"
        data-testid="expiration-time-line"
        style={{
          position: 'absolute',
          left: `${xExpiration}px`,
          top: 0,
          bottom: 0,
          width: isBinmax ? '1.5px' : '2px',
          background: isBinmax ? '#E5484D' : '#ff3d71',
          boxShadow: isBinmax ? '0 0 6px rgba(229, 72, 77, 0.4)' : '0 0 10px rgba(255, 61, 113, 0.75)',
        }}
      >
        {/* Tag Superior: Expiração com Contagem Regressiva */}
        <div
          className="time-tag-expiration"
          data-testid="time-tag-expiration"
          style={{
            position: 'absolute',
            top: isBinmax ? '56px' : '40px',
            left: 0,
            transform: 'translateX(-50%)',
            background: isBinmax ? 'rgba(15, 20, 28, 0.92)' : '#ff3d71',
            border: isBinmax ? '1px solid rgba(229, 72, 77, 0.4)' : 'none',
            color: isBinmax ? '#E5484D' : '#ffffff',
            borderRadius: '6px',
            padding: isBinmax ? '3px 8px' : '2px 8px',
            fontSize: '10px',
            fontWeight: 700,
            letterSpacing: '0.5px',
            whiteSpace: 'nowrap',
            boxShadow: isBinmax ? '0 2px 8px rgba(0, 0, 0, 0.5)' : '0 2px 10px rgba(255, 61, 113, 0.6)',
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            fontFamily: isBinmax ? "'Geist Mono', monospace" : undefined,
          }}
        >
          {isBinmax ? (
            <>
              <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: '#E5484D', boxShadow: '0 0 4px #E5484D', flexShrink: 0 }} />
              <span>EXPIRACIÓN 00:{formattedSeconds}</span>
            </>
          ) : (
            <>
              <span style={{ fontSize: '8px' }}>🔴</span>
              <span>EXPIRACIÓN 00:{formattedSeconds}</span>
            </>
          )}
        </div>

        {/* Ícone no pé da linha (C11) */}
        {isBinmax && (
          <div
            style={{
              position: 'absolute',
              bottom: '12px',
              left: 0,
              transform: 'translateX(-50%)',
              width: '14px',
              height: '14px',
              borderRadius: '50%',
              background: '#E5484D',
              color: '#ffffff',
              display: 'grid',
              placeItems: 'center',
              boxShadow: '0 2px 6px rgba(0,0,0,0.6)',
            }}
            title="Expiración"
          >
            <span style={{ display: 'none' }} aria-hidden="true">🚩</span>
            <svg width={8} height={8} viewBox="0 0 16 16" fill="currentColor">
              <path d="M3 2v12h1.5V9H13l-2-3.5L13 2H3z"/>
            </svg>
          </div>
        )}
      </div>
    </div>
  );
}

import { describe, it, expect, vi } from 'vitest';
import React from 'react';
import { renderToString } from 'react-dom/server';
import { ChartErrorBoundary } from './ChartErrorBoundary';
import { ChartSandbox } from './ChartSandbox';
import { sanitizeTick } from './chart-sanitizer';
import type { Candle } from '../api/client';
import type { Tick } from '../feed/protocol';

describe('SUBETAPA 4: Testes de Caos, Resiliência, Segurança e Blindagem do Gráfico', () => {
  // Componente que simula falha catastrófica interna de WebGL/Canvas
  function CrashyChartRenderer({ shouldExplode }: { shouldExplode: boolean }) {
    if (shouldExplode) {
      throw new Error('FATAL_WEBGL_CONTEXT_LOST: Canvas device context was destroyed by GPU driver reset');
    }
    return <div data-testid="healthy-canvas">Canvas Saudável</div>;
  }

  // Componente irmão (OrderTicket / Wallet)
  function OrderTicketMock({ balance }: { balance: number }) {
    return (
      <div data-testid="order-ticket-mock">
        <span>{`Saldo Disponível: $${balance}`}</span>
        <button type="button">Comprar UP</button>
      </div>
    );
  }

  it('CHAOS-01: Isolamento de Explosão — Crash catastrófico no gráfico NÃO afeta o OrderTicket nem o saldo', () => {
    const errorSpy = vi.fn();

    // Estado 1: Saudável
    const healthyHtml = renderToString(
      <div className="traderoom">
        <ChartErrorBoundary onError={errorSpy}>
          <CrashyChartRenderer shouldExplode={false} />
        </ChartErrorBoundary>
        <OrderTicketMock balance={10000} />
      </div>
    );

    expect(healthyHtml).toContain('data-testid="healthy-canvas"');
    expect(healthyHtml).toContain('data-testid="order-ticket-mock"');
    expect(healthyHtml).toContain('Saldo Disponível: $10000');
    expect(errorSpy).not.toHaveBeenCalled();

    // Estado 2: Gráfico em colapso com boundary ativado
    const boundary = new ChartErrorBoundary({
      onError: errorSpy,
      children: <CrashyChartRenderer shouldExplode={true} />,
    });
    // Força captura de erro no ciclo
    boundary.state = {
      hasError: true,
      error: new Error('FATAL_WEBGL_CONTEXT_LOST'),
      errorInfo: null,
    };

    const crashedTraderoomHtml = renderToString(
      <div className="traderoom">
        {boundary.render()}
        <OrderTicketMock balance={10000} />
      </div>
    );

    // O gráfico exibiu o fallback de segurança sem travar a árvore
    expect(crashedTraderoomHtml).toContain('data-testid="chart-error-fallback"');
    expect(crashedTraderoomHtml).toContain('Gráfico Temporariamente Indisponível');
    // CRUCIAL: O OrderTicket continua 100% montado e renderizado com o saldo de $10.000 intacto!
    expect(crashedTraderoomHtml).toContain('data-testid="order-ticket-mock"');
    expect(crashedTraderoomHtml).toContain('Saldo Disponível: $10000');
    expect(crashedTraderoomHtml).toContain('Comprar UP');
  });

  it('CHAOS-02: Rajada de 50.000 ticks com injeção de dados maliciosos e timestamps retrógrados', () => {
    const maliciousTicks: any[] = [];
    const baseNow = Date.now();

    for (let i = 0; i < 50000; i++) {
      if (i % 100 === 0) {
        // Injeção de payload corrompido ou malicioso
        maliciousTicks.push({
          type: 'tick',
          symbol: 'SYNTH_VOL_50',
          sequence: i,
          price: '<script>alert(1)</script>',
          ts: 'invalido',
        });
      } else if (i % 75 === 0) {
        // Preço negativo ou NaN
        maliciousTicks.push({
          type: 'tick',
          symbol: 'SYNTH_VOL_50',
          sequence: i,
          price: NaN,
          ts: new Date().toISOString(),
        });
      } else {
        // Ticks válidos intercalados com timestamps retrógrados
        maliciousTicks.push({
          type: 'tick',
          symbol: 'SYNTH_VOL_50',
          sequence: i,
          price: (1500 + Math.sin(i) * 10).toFixed(2),
          ts: new Date(baseNow + (i % 2 === 0 ? i * 1000 : -i * 1000)).toISOString(),
        });
      }
    }

    const t0 = performance.now();
    let accepted = 0;
    let rejected = 0;
    let minPrice = Infinity;

    for (const raw of maliciousTicks) {
      const sanitized = sanitizeTick(raw as Tick);
      if (sanitized) {
        accepted++;
        if (sanitized.price < minPrice) minPrice = sanitized.price;
      } else {
        rejected++;
      }
    }

    const duration = performance.now() - t0;
    expect(minPrice).toBeGreaterThan(0);
    expect(rejected).toBeGreaterThan(0); // Garante que todo lixo foi filtrado
    expect(accepted).toBeGreaterThan(0);
    expect(duration).toBeLessThan(300); // 50.000 ticks sanitizados com alta performance
  });

  it('SECURITY-01: Não vaza dados sensíveis, tokens JWT ou credenciais no fallback do gráfico', () => {
    const sensitiveError = new Error('Token expired: eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9.super_secret_jwt');
    const boundary = new ChartErrorBoundary({
      children: <div>Canvas</div>,
    });
    boundary.state = {
      hasError: true,
      error: sensitiveError,
      errorInfo: null,
    };

    const html = renderToString(boundary.render() as React.ReactElement);
    // Deve renderizar a mensagem amigável sem expor dados internos do backend
    expect(html).toContain('Gráfico Temporariamente Indisponível');
    expect(html).toContain('Suas ordens ativas, histórico e saldo demo continuam operando');
  });

  it('LAYOUT-01: CSS Containment isola o canvas contra reflows externos', () => {
    const sampleCandles: Candle[] = [
      { time: 1700000000, open: '100', high: '105', low: '95', close: '102', volume: 0 },
    ];

    const html = renderToString(
      <ChartSandbox
        candles={sampleCandles}
        tick={null}
        symbol="EURUSD_OTC"
      />
    );

    // containment estrito evita reflow no restante do app
    expect(html).toContain('contain:layout size');
    expect(html).toContain('overflow:hidden');
  });
});

import { describe, it, expect, vi } from 'vitest';
import { RafChartUpdater } from './raf-updater';
import { resampleCandles, type Timeframe } from './candle-adapter';
import type { Tick } from '../feed/protocol';
import type { Candle } from '../api/client';

describe('[SUBETAPA 04] Bateria Final de Estresse, Caos e Segurança do Gráfico', () => {
  // ==========================================
  // 1. MATRIZ DE ESTRESSE
  // ==========================================
  describe('Matriz de Estresse Operacional', () => {
    it('STR-01: Rajada de 1.000 ticks em alta frequência — coalescência e estabilidade de thread', () => {
      let renderCalls = 0;
      let scheduledCb: FrameRequestCallback | null = null;

      const updater = new RafChartUpdater((cb) => {
        scheduledCb = cb;
        return 1;
      });

      const startTime = performance.now();

      // Dispara 1.000 ticks consecutivos simulando estresse de alta volatilidade
      for (let i = 1; i <= 1000; i++) {
        updater.push(
          {
            type: 'tick',
            sequence: i,
            symbol: 'SYNTH_VOL_100',
            price: (100 + (i % 50) * 0.2).toFixed(5),
            ts: new Date().toISOString(),
          },
          () => {
            renderCalls++;
          }
        );
      }

      const elapsed = performance.now() - startTime;
      expect(elapsed).toBeLessThan(100); // 1000 pushes processados em <100ms

      const stats = updater.getStats();
      expect(stats.dropped).toBe(999); // 999 ticks coalescidos
      expect(stats.isPending).toBe(true);

      // Descarrega o rAF
      if (scheduledCb) (scheduledCb as FrameRequestCallback)(performance.now());
      expect(renderCalls).toBe(1); // Exatamente 1 frame renderizado
    });

    it('STR-02: Carga e Resample de Janela Macro com 3.500 velas em menos de 50ms', () => {
      const mockCandles: Candle[] = Array.from({ length: 3500 }, (_, i) => ({
        time: 1700000000 + i * 60,
        open: String(100 + (i % 10)),
        high: String(105 + (i % 10)),
        low: String(95 + (i % 10)),
        close: String(102 + (i % 10)),
        volume: 1000,
      }));

      const start = performance.now();
      const resampled5m = resampleCandles(mockCandles, '5m');
      const elapsed = performance.now() - start;

      expect(elapsed).toBeLessThan(50);
      expect(resampled5m.length).toBeGreaterThan(0);
      expect(resampled5m.length).toBeLessThanOrEqual(3500);
    });

    it('STR-03: Comutação veloz de 100 ativos consecutivos resetando cursor e sequências', () => {
      const updater = new RafChartUpdater();

      for (let i = 0; i < 100; i++) {
        updater.resetSequence();
        expect(updater.getStats().lastSequence).toBe('0');

        // Cada novo ativo começa em sequence 1
        updater.push(
          {
            type: 'tick',
            sequence: 1,
            symbol: `SYNTH_ASSET_${i}`,
            price: '150.00',
            ts: new Date().toISOString(),
          },
          vi.fn()
        );
        expect(updater.getStats().lastSequence).toBe('1');
      }
    });
  });

  // ==========================================
  // 2. MATRIZ DE CAOS
  // ==========================================
  describe('Matriz de Caos e Resiliência', () => {
    it('CHS-01: Colapso temporário de dimensões do container (0x0px) não gera exceção', () => {
      const applyOptionsSpy = vi.fn();
      const mockChart = { applyOptions: applyOptionsSpy };

      const safeApplyResize = (w: number, h: number) => {
        if (w > 50 && h > 50) {
          mockChart.applyOptions({ width: w, height: h });
          return true;
        }
        return false;
      };

      // Simula 50 tentativas de resize com container colapsado (0x0, 0x100, 100x0)
      for (let i = 0; i < 50; i++) {
        expect(safeApplyResize(0, 0)).toBe(false);
        expect(safeApplyResize(0, 400)).toBe(false);
        expect(safeApplyResize(600, 0)).toBe(false);
        expect(safeApplyResize(49, 49)).toBe(false);
      }

      expect(applyOptionsSpy).not.toHaveBeenCalled();

      // Recuperação pós-colapso
      expect(safeApplyResize(1024, 600)).toBe(true);
      expect(applyOptionsSpy).toHaveBeenCalledWith({ width: 1024, height: 600 });
    });

    it('CHS-02: Ticks corrompidos ou com preços negativos/NaN são descartados atimicamente', () => {
      const updater = new RafChartUpdater();
      const corruptTicks = [
        { price: 'NaN', sequence: 10 },
        { price: '-10.5', sequence: 11 },
        { price: '0', sequence: 12 },
        { price: 'Infinity', sequence: 13 },
        { price: '-Infinity', sequence: 14 },
        { price: 'abc', sequence: 15 },
        { price: '', sequence: 16 },
      ];

      for (const ct of corruptTicks) {
        updater.push(
          {
            type: 'tick',
            sequence: ct.sequence,
            symbol: 'SYNTH_VOL_50',
            price: ct.price,
            ts: new Date().toISOString(),
          },
          vi.fn()
        );
      }

      expect(updater.getStats().rendered).toBe(0);
      expect(updater.getStats().dropped).toBe(corruptTicks.length);
    });

    it('CHS-03: Recuperação transparente de localStorage corrompido sem crash', () => {
      const corruptStorageValues = [
        '{bad_json: 123',
        'null',
        'undefined',
        '12345',
        '"string"',
        '[{"invalid": true}]',
      ];

      for (const val of corruptStorageValues) {
        let loadedDrawings: any[] = [];
        try {
          const parsed = JSON.parse(val);
          if (Array.isArray(parsed) && parsed.every((d) => d && typeof d.id === 'string')) {
            loadedDrawings = parsed;
          } else {
            loadedDrawings = [];
          }
        } catch {
          loadedDrawings = [];
        }

        expect(Array.isArray(loadedDrawings)).toBe(true);
      }
    });
  });

  // ==========================================
  // 3. MATRIZ DE SEGURANÇA E SANITIZAÇÃO
  // ==========================================
  describe('Matriz de Segurança', () => {
    it('SEC-01: Prevenção de injeção de payload em preço formatado e títulos de cotação', () => {
      const maliciousPayload = '<script>alert(1)</script>';
      const safeNumericPrice = Number(maliciousPayload);

      expect(Number.isFinite(safeNumericPrice)).toBe(false);

      const updater = new RafChartUpdater();
      updater.push(
        {
          type: 'tick',
          sequence: 1,
          symbol: 'SYNTH_VOL_50',
          price: maliciousPayload,
          ts: new Date().toISOString(),
        },
        vi.fn()
      );

      expect(updater.getStats().rendered).toBe(0);
      expect(updater.getStats().dropped).toBe(1);
    });

    it('SEC-02: Validação estrita de identificador de ativo contra path traversal', () => {
      const symbolRegex = /^[A-Z0-9_]{3,32}$/;

      expect(symbolRegex.test('SYNTH_VOL_50')).toBe(true);
      expect(symbolRegex.test('EURUSD_OTC')).toBe(true);
      expect(symbolRegex.test('BTCUSD_OTC')).toBe(true);

      // Ataques de path traversal e injeção
      expect(symbolRegex.test('../../etc/passwd')).toBe(false);
      expect(symbolRegex.test('<script>')).toBe(false);
      expect(symbolRegex.test('VOL;DROP TABLE--')).toBe(false);
      expect(symbolRegex.test('A')).toBe(false); // muito curto
      expect(symbolRegex.test('A'.repeat(33))).toBe(false); // muito longo
    });
  });
});

import { describe, it, expect, vi } from 'vitest';
import React from 'react';
import { renderToString } from 'react-dom/server';
import { ChartErrorBoundary } from './ChartErrorBoundary';
import { RafChartUpdater } from './raf-updater';
import type { Tick } from '../feed/protocol';

describe('[FASE 2 HARDENING] Blindagem Avançada, Auto-Heal e Resiliência WebGL/CPU', () => {
  it('HARD-01: Auto-Heal recupera automaticamente o gráfico após falha transitória', async () => {
    const onReset = vi.fn();
    const boundary = new ChartErrorBoundary({
      symbol: 'BTCUSD_OTC',
      autoHeal: true,
      maxAutoRetries: 2,
      autoRetryDelayMs: 15,
      onReset,
      children: <div>Canvas</div>,
    });

    const error = new Error('GPU_DRIVER_RESET');
    const errorInfo: React.ErrorInfo = { componentStack: '\n    in PriceChart' };

    boundary.componentDidCatch(error, errorInfo);

    // Imediatamente após o crash: isAutoHealing está ativo
    expect(boundary.state.isAutoHealing).toBe(true);
    expect(boundary.state.autoRetriesCount).toBe(0);

    // Aguarda o timer de auto-cura expirar (15ms + margem)
    await new Promise((resolve) => setTimeout(resolve, 35));

    // Estado auto-curado: hasError resetado para false e retries incrementado
    expect(boundary.state.hasError).toBe(false);
    expect(boundary.state.autoRetriesCount).toBe(1);
    expect(boundary.state.isAutoHealing).toBe(false);
    expect(onReset).toHaveBeenCalledTimes(1);
  });

  it('HARD-02: Auto-Heal exibe indicador visual de auto-recuperação durante a transição', () => {
    const boundary = new ChartErrorBoundary({
      symbol: 'BTCUSD_OTC',
      children: <div>Canvas</div>,
    });

    boundary.state = {
      hasError: true,
      error: new Error('WebGL Lost'),
      errorInfo: null,
      autoRetriesCount: 0,
      isAutoHealing: true,
    };

    const html = renderToString(boundary.render() as React.ReactElement);
    expect(html).toContain('data-testid="auto-healing-indicator"');
    expect(html).toContain('Tentando auto-recuperação transparente');
  });

  it('HARD-03: WebGL Context Lost previne default para permitir restauração pela GPU', () => {
    let defaultPrevented = false;
    const fakeEvent = {
      type: 'webglcontextlost',
      preventDefault: () => {
        defaultPrevented = true;
      },
    };

    // Simula a rotina obrigatória do padrão Khronos WebGL
    const handleContextLost = (e: any) => {
      e.preventDefault();
    };

    handleContextLost(fakeEvent);
    expect(defaultPrevented).toBe(true);
  });

  it('HARD-04: RafChartUpdater monitora duração do frame e detecta alta carga de CPU (>25ms)', () => {
    let queuedCb: ((time: number) => void) | null = null;
    const customRaf = (cb: (time: number) => void) => {
      queuedCb = cb;
      return 1;
    };

    const updater = new RafChartUpdater(customRaf);

    const heavyRenderCallback = vi.fn(() => {
      // Simula renderização pesada que consome 30ms
      const start = Date.now();
      while (Date.now() - start < 30) {
        // busy wait
      }
    });

    const mockTick: Tick = {
      type: 'tick',
      symbol: 'SYNTH_VOL_50',
      sequence: 1,
      price: '1500.25',
      ts: new Date().toISOString(),
    };

    updater.push(mockTick, heavyRenderCallback);

    // Executa o frame
    if (queuedCb) (queuedCb as any)(performance.now());

    const stats = updater.getStats();
    expect(stats.rendered).toBe(1);
    expect(stats.lastFrameDurationMs).toBeGreaterThanOrEqual(25);
    expect(stats.highLoadFramesCount).toBeGreaterThanOrEqual(1);
  });
});

