    const drawings = loadSafeDrawings('SYNTH_VOL_50');
    expect(drawings).toEqual([]); // Retorna array vazio sem travar a thread
  });

  it('DS-06: saveSafeDrawings e loadSafeDrawings persistem e recuperam dados sanitizados', () => {
