      expect(atr.length).toBeGreaterThan(900);
      expect(vwap.length).toBe(1000);
      expect(cci.length).toBeGreaterThan(900);

      // O tempo total para os 10 indicadores sobre 1.000 barras não pode exceder 1500ms sob carga paralela pesada
      expect(elapsed).toBeLessThan(1500);
    });

    it('suporta períodos longos (SMA 200 e EMA 200) sem estourar pilha de recursão', () => {
      expect(() => calculateSMA(largeCandleDataset, 200)).not.toThrow();
      expect(() => calculateEMA(largeCandleDataset, 200)).not.toThrow();
      expect(() => calculateWMA(largeCandleDataset, 200)).not.toThrow();
    });
  });

  describe('2. Testes de Caos e Anomalias de Dados', () => {
    it('resiste a velas com volume zerado, negativo ou string alfanumérica', () => {
      const corruptCandles = [
        { time: 1700000000, open: '100', high: '110', low: '90', close: '105', volume: '0' },
        { time: 1700000060, open: '105', high: '115', low: '95', close: '110', volume: '-50' },
        { time: 1700000120, open: '110', high: '120', low: '100', close: '115', volume: 'invalid_vol' },
      ];

      const vwap = calculateVWAP(corruptCandles as any);
      expect(vwap).toHaveLength(3);
      for (const pt of vwap) {
        expect(Number.isFinite(pt.value)).toBe(true);
        expect(pt.value).toBeGreaterThan(0);
      }
    });

    it('resiste a timestamps misturados (ms x s x ISO)', () => {
      const mixedCandles = [
        { time: 1700000000000, close: '100' }, // ms (> 10^10)
        { time: 1700000060, close: '102' },    // s
        { open_time: '2026-10-07T00:02:00Z', close: '104' }, // ISO string
      ];

      const sma = calculateSMA(mixedCandles, 2);
      expect(sma).toHaveLength(2);
      expect(sma[0].time).toBe(1700000060);
      expect(sma[1].time).toBe(Math.floor(Date.parse('2026-10-07T00:02:00Z') / 1000));
    });

    it('lida com spread zero absoluto (high = low = open = close) sem gerar NaN no ATR ou Estocástico', () => {
      const flatCandles: Candle[] = Array.from({ length: 20 }, (_, i) => ({
        time: 1700000000 + i * 60,
        open: '500',
        high: '500',
        low: '500',
        close: '500',
        volume: 10,
      }));

      const atr = calculateATR(flatCandles, 14);
      expect(atr.length).toBeGreaterThan(0);
      expect(atr[0].value).toBe(0);

      const stoch = calculateStochastic(flatCandles, 14, 3);
      expect(stoch.length).toBeGreaterThan(0);
      expect(stoch[0].k).toBe(50); // Neutro
      expect(stoch[0].d).toBe(50);
    });
  });

  describe('3. Testes de Segurança Numérica', () => {
    it('garante que nenhum valor retornado seja NaN, null ou undefined', () => {
      const indicatorsResults = [
        calculateSMA(largeCandleDataset.slice(0, 50), 10),
        calculateEMA(largeCandleDataset.slice(0, 50), 10),
        calculateWMA(largeCandleDataset.slice(0, 50), 10),
        calculateRSI(largeCandleDataset.slice(0, 50), 14),
        calculateATR(largeCandleDataset.slice(0, 50), 14),
        calculateVWAP(largeCandleDataset.slice(0, 50)),
        calculateCCI(largeCandleDataset.slice(0, 50), 14),
      ];

      for (const res of indicatorsResults) {
        for (const pt of res) {
          expect(Number.isFinite(pt.value)).toBe(true);
          expect(Number.isNaN(pt.value)).toBe(false);
        }
      }

      const bbands = calculateBollinger(largeCandleDataset.slice(0, 50), 10, 2);
      for (const b of bbands) {
        expect(Number.isFinite(b.upper)).toBe(true);
        expect(Number.isFinite(b.middle)).toBe(true);
        expect(Number.isFinite(b.lower)).toBe(true);
      }

      const macd = calculateMACD(largeCandleDataset.slice(0, 50), 12, 26, 9);
      for (const m of macd) {
        expect(Number.isFinite(m.macd)).toBe(true);
        expect(Number.isFinite(m.signal)).toBe(true);
        expect(Number.isFinite(m.histogram)).toBe(true);
      }

      const stoch = calculateStochastic(largeCandleDataset.slice(0, 50), 14, 3);
      for (const s of stoch) {
        expect(Number.isFinite(s.k)).toBe(true);
        expect(Number.isFinite(s.d)).toBe(true);
      }
    });
  });
});

import React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { renderToString } from 'react-dom/server';
import { MultiChartGrid, type GridLayout } from './MultiChartGrid';
import { normalizeSeedWithTick, safeCandleFromTick, detectPriceScaleAnomaly } from './chart-scale-normalizer';
import type { Candle } from '../api/client';
import type { Tick } from '../feed/protocol';

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

describe('[SUBETAPA 03] Testes de Caos, Estresse e Isolamento Multi-Gráficos', () => {
  const dummyContracts: any[] = [];
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });

  it('CHAOS-01: MultiChartGrid renderiza layouts 1x1, 2x1, 2x2 e 3x2 sem exceptions no SSR/DOM', () => {
    const layouts: GridLayout[] = ['1x1', '2x1', '2x2', '3x2'];

    for (const layout of layouts) {
      const html = renderToString(
        <QueryClientProvider client={queryClient}>
          <MultiChartGrid
            activeSymbol="EURUSD_OTC"
            onActiveSymbolChange={vi.fn()}
            allContracts={dummyContracts}
            layout={layout}
          />
        </QueryClientProvider>
      );
      expect(html).toBeDefined();
      expect(html.length).toBeGreaterThan(50);
    }
  });

  it('CHAOS-02: Isolamento Estrito: 6 gráficos com símbolos heterogêneos recebem rajadas sem contaminação cruzada', () => {
    const symbols = [
      'EURUSD_OTC',
      'BTCUSD_OTC',
      'XAUUSD_OTC',
      'SYNTH_VOL_50',
      'ETHUSD_OTC',
      'SOLUSD_OTC',
    ];

    const symbolPrices: Record<string, number> = {
      EURUSD_OTC: 1.0854,
      BTCUSD_OTC: 64850.0,
      XAUUSD_OTC: 2652.8,
      SYNTH_VOL_50: 1250.0,
      ETHUSD_OTC: 3450.0,
      SOLUSD_OTC: 152.4,
    };

    // Gera 1.000 rajadas de ticks distribuídas aleatoriamente entre os símbolos
    for (let i = 0; i < 1000; i++) {
      const sym = symbols[i % symbols.length];
      const base = symbolPrices[sym];
      const tickPrice = (base * (1 + (Math.sin(i) * 0.001))).toFixed(4);

      const tick: Tick = {
        type: 'tick',
        sequence: i + 1,
        symbol: sym,
        price: tickPrice,
        ts: new Date((1700000000 + i) * 1000).toISOString(),
      };

      const seed: Candle[] = [
        {
          time: 1700000000,
          open: String(base),
          high: String(base * 1.001),
          low: String(base * 0.999),
          close: String(base),
          volume: 10,
        },
      ];

      const normalized = normalizeSeedWithTick(seed, tick);
      expect(normalized.length).toBe(1);

      // Garante que o candle do EURUSD nunca assuma preço de BTCUSD ou vice-versa
      const closeNum = Number(normalized[0].close);
      if (sym === 'EURUSD_OTC') {
        expect(closeNum).toBeLessThan(2.0);
      } else if (sym === 'BTCUSD_OTC') {
        expect(closeNum).toBeGreaterThan(50000.0);
      }
    }
  });

  it('CHAOS-03: Resiliência contra Ticks Tóxicos (NaN, negativos, timestamps corrompidos)', () => {
    const prev = {
      time: 1700000000 as any,
      open: 1.0854,
      high: 1.0860,
      low: 1.0850,
      close: 1.0855,
    };

    const toxicTicks: any[] = [
      { symbol: 'EURUSD_OTC', price: null, ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: undefined, ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: 'Infinity', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '-999.0', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '0', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '1.0856', ts: 'invalid_date' },
      null,
      undefined,
    ];

    for (const toxic of toxicTicks) {
      const res = safeCandleFromTick(toxic, prev, '1m');
      // Deve descartar silenciosamente sem jogar exception nem corromper
      expect(res).toBeNull();
    }
  });

  it('CHAOS-04: Transição rápida entre escalas ordinais opostas é detectada com sucesso', () => {
    // BTC para EURUSD
    expect(detectPriceScaleAnomaly(64850.0, 1.0854)).toBe(true);
    // EURUSD para BTC
    expect(detectPriceScaleAnomaly(1.0854, 64850.0)).toBe(true);
    // Preços próximos
    expect(detectPriceScaleAnomaly(100.0, 100.5)).toBe(false);
  });
});

