import { describe, it, expect, vi } from 'vitest';
import { RafChartUpdater } from './raf-updater';
import type { Tick } from '../feed/protocol';

describe('SUBETAPA 01: Desbloqueio Sequencial e Isolamento Multi-Ativo no RafUpdater', () => {
  it('deve processar ticks de novo ativo mesmo quando a sequência numérica for inferior ao ativo anterior', () => {
    let capturedRafCb: FrameRequestCallback | null = null;
    const mockRaf = vi.fn((cb: FrameRequestCallback) => {
      capturedRafCb = cb;
      return 1;
    });
    const mockCancelRaf = vi.fn();

    const updater = new RafChartUpdater(mockRaf, mockCancelRaf);
    const renderedTicks: Tick[] = [];
    const onRender = (t: Tick) => renderedTicks.push(t);

    // 1. Envia ticks para SYNTH_VOL_50 com sequência alta (50.000)
    updater.push(
      { type: 'tick', symbol: 'SYNTH_VOL_50', sequence: 50000, price: '1000.50', ts: new Date().toISOString() },
      onRender
    );
    expect(mockRaf).toHaveBeenCalledTimes(1);
    capturedRafCb!(performance.now());
    expect(renderedTicks.length).toBe(1);
    expect(renderedTicks[0].symbol).toBe('SYNTH_VOL_50');

    // 2. Agora o usuário alterna para EURUSD_OTC que inicia em sequência baixa (100)
    // Sem isolamento multissímbolo, este tick seria descartado como duplicata defasada (100 <= 50000)
    updater.push(
      { type: 'tick', symbol: 'EURUSD_OTC', sequence: 100, price: '1.08500', ts: new Date().toISOString() },
      onRender
    );
    expect(mockRaf).toHaveBeenCalledTimes(2);
    capturedRafCb!(performance.now());

    expect(renderedTicks.length).toBe(2);
    expect(renderedTicks[1].symbol).toBe('EURUSD_OTC');
    expect(renderedTicks[1].price).toBe('1.08500');

    // 3. Verifica que a sequência interna de EURUSD_OTC continua estritamente monotônica
    // Tick com seq 99 em EURUSD_OTC deve ser descartado
    updater.push(
      { type: 'tick', symbol: 'EURUSD_OTC', sequence: 99, price: '1.08510', ts: new Date().toISOString() },
      onRender
    );
    expect(mockRaf).toHaveBeenCalledTimes(2); // Não disparou novo rAF
    expect(updater.getStats().dropped).toBe(1);

    // Tick com seq 101 em EURUSD_OTC deve ser aceito
    updater.push(
      { type: 'tick', symbol: 'EURUSD_OTC', sequence: 101, price: '1.08520', ts: new Date().toISOString() },
      onRender
    );
    expect(mockRaf).toHaveBeenCalledTimes(3);
    capturedRafCb!(performance.now());
    expect(renderedTicks.length).toBe(3);
    expect(renderedTicks[2].sequence).toBe(101);
  });

  it('reset(symbol) deve expurgar a sequência e o tick pendente sem vazar para o próximo ciclo', () => {
    let capturedRafCb: FrameRequestCallback | null = null;
    const mockRaf = vi.fn((cb: FrameRequestCallback) => {
      capturedRafCb = cb;
      return 42;
    });
    const mockCancelRaf = vi.fn();

    const updater = new RafChartUpdater(mockRaf, mockCancelRaf);
    const renderedTicks: Tick[] = [];

    // Enfileira tick de BTCUSD
    updater.push(
      { type: 'tick', symbol: 'BTCUSD_OTC', sequence: 9999, price: '64000.00', ts: new Date().toISOString() },
      (t) => renderedTicks.push(t)
    );
    expect(updater.getStats().isPending).toBe(true);

    // Reset chamado ao trocar de tela / ativo
    updater.reset('BTCUSD_OTC');
    expect(mockCancelRaf).toHaveBeenCalledWith(42);
    expect(updater.getStats().isPending).toBe(false);

    // Se o rAF antigo disparar por anomalia do browser, nada deve ser processado
    const cb = capturedRafCb as ((time: number) => void) | null;
    if (cb) {
      cb(performance.now());
    }
    expect(renderedTicks.length).toBe(0);
  });

  it('Stress Test: rajada de 2.000 ticks entre 4 pares simultâneos sem corrupção de estado', () => {
    const executedTicks: Tick[] = [];
    // Executa callbacks síncronos imediatos para estressar o motor
    const syncRaf = (cb: FrameRequestCallback) => {
      cb(performance.now());
      return 1;
    };
    const updater = new RafChartUpdater(syncRaf as any, vi.fn());

    const symbols = ['SYNTH_VOL_50', 'EURUSD_OTC', 'BTCUSD_OTC', 'ETHUSD_OTC'];
    const counters = { SYNTH_VOL_50: 1000, EURUSD_OTC: 50, BTCUSD_OTC: 500000, ETHUSD_OTC: 10 };

    for (let i = 0; i < 2000; i++) {
      const sym = symbols[i % symbols.length];
      counters[sym as keyof typeof counters] += 1;
      const seq = counters[sym as keyof typeof counters];

      updater.push(
        {
          type: 'tick',
          symbol: sym,
          sequence: seq,
          price: (100 + i * 0.01).toFixed(4),
          ts: new Date().toISOString(),
        },
        (t) => executedTicks.push(t)
      );
    }

    expect(executedTicks.length).toBe(2000);
    const stats = updater.getStats();
    expect(stats.dropped).toBe(0);
    expect(stats.rendered).toBe(2000);
  });
});

import { describe, it, expect, vi } from 'vitest';
import { RafChartUpdater } from './raf-updater';
import type { Tick } from '../feed/protocol';

describe('[SUBETAPA 02] RafChartUpdater — Motor rAF e Ciclo de Vida de Ticks', () => {
  const createMockTick = (price: string | number, sequence: number): Tick => ({
    type: 'tick',
    sequence,
    symbol: 'SYNTH_VOL_50',
    price: String(price),
    ts: new Date().toISOString(),
    event_time: Date.now(),
    latency_ms: 12,
  });

  it('RAF-01: Coalesce rajada de 100 ticks consecutivos no mesmo frame gerando exatamente 1 render', () => {
    let queuedCb: FrameRequestCallback | null = null;
    const customRaf = (cb: FrameRequestCallback) => {
      queuedCb = cb;
      return 1;
    };
    const customCancel = vi.fn();

    const updater = new RafChartUpdater(customRaf, customCancel);
    const renderCallback = vi.fn();

    // Dispara 100 ticks velozes com sequência estritamente crescente
    for (let i = 1; i <= 100; i++) {
      updater.push(createMockTick(100 + i * 0.1, i), renderCallback);
    }

    const statsBefore = updater.getStats();
    expect(statsBefore.dropped).toBe(99); // 99 descartados por coalescência
    expect(statsBefore.isPending).toBe(true);
    expect(renderCallback).not.toHaveBeenCalled();

    // Executa o frame de 60fps acumulado
    if (queuedCb) (queuedCb as FrameRequestCallback)(performance.now());

    expect(renderCallback).toHaveBeenCalledTimes(1);
    expect(renderCallback).toHaveBeenCalledWith(
      expect.objectContaining({
        price: '110', // Último tick consolidado
        sequence: 100,
      })
    );

    const statsAfter = updater.getStats();
    expect(statsAfter.rendered).toBe(1);
    expect(statsAfter.isPending).toBe(false);
  });

  it('RAF-02: Descarta defensivamente preços malformados (NaN, <= 0, strings inválidas)', () => {
    const customRaf = vi.fn();
    const updater = new RafChartUpdater(customRaf);
    const renderCallback = vi.fn();

    // Ticks com preços ilegais
    updater.push({ ...createMockTick('100', 1), price: 'NaN' }, renderCallback);
    updater.push({ ...createMockTick('100', 2), price: '-50.2' }, renderCallback);
    updater.push({ ...createMockTick('100', 3), price: '0' }, renderCallback);
    updater.push({ ...createMockTick('100', 4), price: 'null' }, renderCallback);

    expect(customRaf).not.toHaveBeenCalled();
    expect(updater.getStats().dropped).toBe(4);
    expect(updater.getStats().isPending).toBe(false);
  });

  it('RAF-03: Monotonicidade estrita — descarta ticks fora de ordem ou duplicados (F-06)', () => {
    let queuedCb: ((time: number) => void) | null = null;
    const updater = new RafChartUpdater((cb) => {
      queuedCb = cb;
      return 1;
    });
    const renderCallback = vi.fn();

    // Tick 10
    updater.push(createMockTick(105, 10), renderCallback);
    if (queuedCb) (queuedCb as any)(performance.now());
    expect(renderCallback).toHaveBeenCalledTimes(1);

    // Ticks antigos chegando com atraso de rede (sequence 8 e 9)
    updater.push(createMockTick(104, 8), renderCallback);
    updater.push(createMockTick(104.5, 9), renderCallback);
    updater.push(createMockTick(105, 10), renderCallback); // duplicado

    // Nenhum render deve ser agendado para ticks defasados
    expect(updater.getStats().isPending).toBe(false);
    expect(renderCallback).toHaveBeenCalledTimes(1);

    // Tick 11 válido avança o cursor
    updater.push(createMockTick(106, 11), renderCallback);
    expect(updater.getStats().isPending).toBe(true);
    if (queuedCb) (queuedCb as any)(performance.now());
    expect(renderCallback).toHaveBeenCalledTimes(2);
  });

  it('RAF-04: Pausa e retomada graciosa sem acúmulo de frames quando em segundo plano', () => {
    const cancelSpy = vi.fn();
    let queuedCb: ((time: number) => void) | null = null;
    const updater = new RafChartUpdater(
      (cb) => {
        queuedCb = cb;
        return 999;
      },
      cancelSpy
    );
    const renderCallback = vi.fn();

    updater.push(createMockTick(100, 1), renderCallback);
    expect(updater.getStats().isPending).toBe(true);

    // Entra em segundo plano (aba oculta)
    updater.pause();
    expect(cancelSpy).toHaveBeenCalledWith(999);
    expect(updater.getStats().isPaused).toBe(true);

    // Novos ticks enquanto pausado são retidos sem agendar rAF
    updater.push(createMockTick(101, 2), renderCallback);
    expect(updater.getStats().isPending).toBe(true);

    // Volta ao primeiro plano (aba ativa)
    updater.resume(renderCallback);
    expect(updater.getStats().isPaused).toBe(false);
    if (queuedCb) (queuedCb as any)(performance.now());
    expect(renderCallback).toHaveBeenCalledWith(expect.objectContaining({ price: '101' }));
  });

  it('RAF-05: Reset de sequência permite alternância segura entre múltiplos ativos', () => {
    const updater = new RafChartUpdater();
    updater.push(createMockTick(100, 5000), vi.fn());
    expect(updater.getStats().lastSequence).toBe('5000');

    // Ao mudar de ativo, a sequência do novo ativo pode começar em 1
    updater.resetSequence();
    expect(updater.getStats().lastSequence).toBe('0');

    // Aceita sequência menor após o reset
    updater.push(createMockTick(200, 1), vi.fn());
    expect(updater.getStats().lastSequence).toBe('1');
  });
});

import { describe, it, expect } from 'vitest';
import { getAssetBasePrice, ASSET_BASE_PRICES } from '../catalog/assets';
import { generateSeedCandles } from '../api/client';
import { safeCandleFromTick, detectPriceScaleAnomaly } from './chart-scale-normalizer';
import type { Tick } from '../feed/protocol';

describe('[SUBETAPA 01 REVISADA] Paridade de Preços Base e Estabilização de Escala Gráfica', () => {
  it('SCALE-01: Paridade Rigorosa: SYNTH_VOL_50 tem preço base exato de 500.1250 idêntico ao backend', () => {
    const basePrice = getAssetBasePrice('SYNTH_VOL_50');
    expect(basePrice).toBe(500.125);
    expect(ASSET_BASE_PRICES['SYNTH_VOL_50']).toBe(500.125);
  });

  it('SCALE-02: Zero Vela Gigante: A semente de 2.880 velas de SYNTH_VOL_50 termina próxima do preço do primeiro tick', () => {
    const candles = generateSeedCandles('SYNTH_VOL_50', 2880);
    expect(candles.length).toBe(2880);
    const lastCandle = candles[candles.length - 1];
    const lastClose = Number(lastCandle.close);

    // O preço final gerado pela semente deve estar na ordem de 500.125 (e NUNCA 1250.0!)
    expect(lastClose).toBeGreaterThan(400.0);
    expect(lastClose).toBeLessThan(650.0);

    // Quando o primeiro tick do backend chega em 500.1250:
    const firstTick: Tick = {
      type: 'tick',
      sequence: 1,
      symbol: 'SYNTH_VOL_50',
      price: '500.1250',
      ts: new Date().toISOString(),
    };

    const prevCandle = {
      time: Math.floor(Date.now() / 60000) * 60 as any,
      open: lastClose,
      high: Number(lastCandle.high),
      low: Number(lastCandle.low),
      close: lastClose,
    };

    const next = safeCandleFromTick(firstTick, prevCandle, '1m');
    expect(next).not.toBeNull();
    // A variação entre o último close da semente e o primeiro tick NÃO pode exceder 30%
    const jumpPercent = Math.abs(Number(next!.close) - lastClose) / lastClose * 100;
    expect(jumpPercent).toBeLessThan(30);
  });

  it('SCALE-03: Reset de Escala: Transição de BTCUSD ($64.850) para EURUSD ($1.0854) é flagrada como anomalia para reset imediato', () => {
