import React, { useEffect, useRef } from "react";
import { createChart, IChartApi, ISeriesApi, CandlestickData, Time } from "lightweight-charts";

interface TradingViewCanvasProps {
  symbol: string;
  lastTick: { sequence: string; price: string; ts: string } | null;
  activeContractPrice?: number | null;
}

export const TradingViewCanvas: React.FC<TradingViewCanvasProps> = ({
  symbol,
  lastTick,
  activeContractPrice
}) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const priceLineRef = useRef<any>(null);
  const lastSequenceRef = useRef<bigint>(0n);

  useEffect(() => {
    if (!chartContainerRef.current) return;

    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: chartContainerRef.current.clientHeight,
      layout: {
        background: { color: "#0B0E14" },
        textColor: "#9B9FA4"
      },
      grid: {
        vertLines: { color: "#1E222D" },
        horzLines: { color: "#1E222D" }
      },
      timeScale: {
        timeVisible: true,
        secondsVisible: true,
        borderColor: "#2B2F3A"
      },
      rightPriceScale: {
        borderColor: "#2B2F3A"
      }
    });

    const candlestickSeries = chart.addCandlestickSeries({
      upColor: "#089981",
      downColor: "#F23645",
      borderVisible: false,
      wickUpColor: "#089981",
      wickDownColor: "#F23645"
    });

    chartRef.current = chart;
    seriesRef.current = candlestickSeries;

    // Carga de histórico inicial via REST UDF (D-03)
    const loadHistory = async () => {
      try {
        const to = Math.floor(Date.now() / 1000);
        const from = to - 3600; // Última 1 hora
        const res = await fetch(`/api/v1/chart/history?symbol=${symbol}&resolution=1&from=${from}&to=${to}`);
        const data = await res.json();

        if (data.s === "ok" && data.t) {
          const bars: CandlestickData[] = data.t.map((t: number, i: number) => ({
            time: t as Time,
            open: data.o[i],
            high: data.h[i],
            low: data.l[i],
            close: data.c[i]
          }));
          candlestickSeries.setData(bars);
        }
      } catch (err) {
        console.error("Failed to load chart history:", err);
      }
    };

    loadHistory();

    const handleResize = () => {
      if (chartContainerRef.current && chartRef.current) {
        chartRef.current.applyOptions({
          width: chartContainerRef.current.clientWidth,
          height: chartContainerRef.current.clientHeight
        });
      }
    };

    const resizeObserver = new ResizeObserver(handleResize);
    resizeObserver.observe(chartContainerRef.current);

    return () => {
      resizeObserver.disconnect();
      chart.remove();
    };
  }, [symbol]);

  // Atualização em tempo real da vela atual com o tick recebido via WebSocket
  useEffect(() => {
    if (!lastTick || !seriesRef.current) return;

    const seq = BigInt(lastTick.sequence);
    // Descarte rigoroso de ticks fora de ordem ou duplicados (F-06)
    if (seq <= lastSequenceRef.current) {
      return;
    }
    lastSequenceRef.current = seq;

    const tickTimeSec = Math.floor(new Date(lastTick.ts).getTime() / 1000);
    // Alinhamento ao bucket de 1 minuto em segundos
    const candleTimeSec = Math.floor(tickTimeSec / 60) * 60;
    const price = parseFloat(lastTick.price);

    seriesRef.current.update({
      time: candleTimeSec as Time,
      open: price,
      high: price,
      low: price,
      close: price
    });
  }, [lastTick]);

  // Atualiza linha de preço de entrada para ordens ativas
  useEffect(() => {
    if (!seriesRef.current) return;

    if (priceLineRef.current) {
      seriesRef.current.removePriceLine(priceLineRef.current);
      priceLineRef.current = null;
    }

    if (activeContractPrice) {
      priceLineRef.current = seriesRef.current.createPriceLine({
        price: activeContractPrice,
        color: "#F6C344",
        lineWidth: 2,
        lineStyle: 2, // Tracejado
        axisLabelVisible: true,
        title: "ENTRADA"
      });
    }
  }, [activeContractPrice]);

  return (
    <div
      ref={chartContainerRef}
      style={{
        width: "100%",
        height: "100%",
        position: "relative"
      }}
    />
  );
};

import React, { useState } from 'react';
import type { Contract } from '../../api/client';
import { AssetFlagBadge } from '../header/AssetFlagBadge';

export interface BinmaxHistoryDrawerProps {
  contracts: Contract[];
  onClose?: () => void;
}

export const BinmaxHistoryDrawer: React.FC<BinmaxHistoryDrawerProps> = ({
  contracts,
  onClose,
}) => {
  const [filter, setFilter] = useState<'TODOS' | 'WIN' | 'LOSS'>('TODOS');

  const settled = contracts.filter((c) => c.status !== 'OPEN');
  const filtered = settled.filter((c) => {
    if (filter === 'WIN') return c.result === 'WIN';
    if (filter === 'LOSS') return c.result === 'LOSS';
    return true;
  });

  return (
    <div
      data-testid="binmax-history-drawer"
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        color: '#F4F5F7',
        fontFamily: "'Geist', sans-serif",
      }}
    >
      {/* Filtro de Resultado Dropdown Estilo Prancha 6 */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: '14px',
        }}
      >
        <span style={{ fontSize: '11px', color: '#8A92A1', fontWeight: 600 }}>Filtrar:</span>
        <select
          data-testid="history-filter-select"
          value={filter}
          onChange={(e) => setFilter(e.target.value as any)}
          style={{
            background: '#151922',
            border: '1px solid rgba(244, 245, 247, 0.12)',
            borderRadius: '6px',
            color: '#F4F5F7',
            padding: '4px 8px',
            fontSize: '11px',
            fontFamily: "'Geist', sans-serif",
            outline: 'none',
            cursor: 'pointer',
          }}
        >
          <option value="TODOS">Resultado: Todos</option>
          <option value="WIN">Ganadas</option>
          <option value="LOSS">Perdidas</option>
        </select>
      </div>

      {/* Agrupador Temporal: Hoy */}
      <div
        style={{
          fontSize: '11px',
          fontWeight: 700,
          color: '#8A92A1',
          padding: '4px 0',
          borderBottom: '1px solid rgba(244, 245, 247, 0.06)',
          marginBottom: '8px',
        }}
      >
        Hoy
      </div>

      {/* Lista de Cards de Histórico (Sessão 6) */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px 10px', color: '#8A92A1', fontSize: '12px' }}>
          No hay operaciones en este filtro.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          {filtered.map((c) => {
            const isWin = c.result === 'WIN';
            const isUp = c.direction === 'UP';
            const stake = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
            const stakeDollars = Math.round(stake / 100);

            const payout = typeof c.payout_minor === 'string' ? parseInt(c.payout_minor, 10) : (c.payout_minor ?? 0);
            const profitDollars = isWin ? ((payout - stake) / 100).toFixed(2) : stakeDollars.toFixed(2);
            const formattedResult = isWin ? `+$${profitDollars}` : `-$${profitDollars}`;

            const timeStr = new Date(c.created_at).toLocaleTimeString('es-ES', {
              hour: '2-digit',
              minute: '2-digit',
              hour12: false,
            });

            const cleanSym = c.symbol.replace('_OTC', '').replace(/([A-Z]{3})([A-Z]{3})/, '$1/$2');

            return (
              <div
                key={c.id}
                data-testid={`history-card-${c.id}`}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '9px 12px',
                  background: 'rgba(21, 25, 34, 0.75)',
                  border: '1px solid rgba(244, 245, 247, 0.06)',
                  borderRadius: '6px',
                }}
              >
                {/* Lado Esquerdo: Bandeira + Ativo + Horário */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <AssetFlagBadge symbol={c.symbol} size={18} />
                  <div style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.15 }}>
                    <strong style={{ fontSize: '11.5px', color: '#F4F5F7' }}>{cleanSym}</strong>
                    <span style={{ fontSize: '9px', color: '#8A92A1', fontFamily: "'Geist Mono', monospace" }}>
                      {timeStr}
                    </span>
                  </div>
                </div>

                {/* Centro: Tag SUBE/BAJA + Montante */}
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                    fontSize: '11px',
                    color: isUp ? '#22C47A' : '#F2545B',
                    fontFamily: "'Geist Mono', monospace",
                    fontWeight: 700,
                  }}
                >
                  <span>{isUp ? '▲ SUBE' : '▼ BAJA'}</span>
                  <span style={{ color: '#DCE1EA' }}>${stakeDollars}</span>
                </div>

                {/* Lado Direito: Lucro/Prejuízo Consolidado */}
                <strong
                  data-testid={`history-result-${c.id}`}
                  style={{
                    fontSize: '12px',
                    color: isWin ? '#22C47A' : '#F2545B',
                    fontFamily: "'Geist Mono', monospace",
                  }}
                >
                  {formattedResult}
                </strong>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import type { Contract } from '../../api/client';
import { AssetFlagBadge } from '../header/AssetFlagBadge';

export interface BinmaxPortfolioDrawerProps {
  contracts: Contract[];
  currentPrice: number | string | null;
  onClose?: () => void;
}

export const BinmaxPortfolioDrawer: React.FC<BinmaxPortfolioDrawerProps> = ({
  contracts,
  currentPrice,
  onClose,
}) => {
  const [activeTab, setActiveTab] = useState<'abiertas' | 'cerradas'>('abiertas');
  const [now, setNow] = useState<number>(() => Date.now());

  const openContracts = contracts.filter((c) => c.status === 'OPEN');
  const closedContracts = contracts.filter((c) => c.status !== 'OPEN');

  const displayedContracts = activeTab === 'abiertas' ? openContracts : closedContracts;

  // Atualização em tempo real de segundo a segundo enquanto houver operações abertas
  useEffect(() => {
    if (openContracts.length === 0) return;
    const timer = setInterval(() => {
      setNow(Date.now());
    }, 1000);
    return () => clearInterval(timer);
  }, [openContracts.length]);

  return (
    <div
      data-testid="binmax-portfolio-drawer"
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        color: '#F4F5F7',
        fontFamily: "'Geist', sans-serif",
      }}
    >
      {/* Abas Estilo Underline: Abiertas N e Cerradas (Referência IQ/Binmax) */}
      <div
        style={{
          display: 'flex',
          borderBottom: '1px solid rgba(244, 245, 247, 0.1)',
          marginBottom: '14px',
        }}
      >
        <button
          type="button"
          data-testid="tab-portfolio-abiertas"
          onClick={() => setActiveTab('abiertas')}
          style={{
            background: 'transparent',
            border: 'none',
            borderBottom: activeTab === 'abiertas' ? '2px solid #FFFFFF' : '2px solid transparent',
            color: activeTab === 'abiertas' ? '#FFFFFF' : '#8A92A1',
            padding: '8px 16px 10px 16px',
            fontSize: '13px',
            fontWeight: 700,
            cursor: 'pointer',
            transition: 'color 0.15s ease, border-color 0.15s ease',
            marginBottom: '-1px',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
          }}
        >
          <span>{`Abiertas ${openContracts.length}`}</span>
          <span style={{ display: 'none' }} aria-hidden="true">
            {`Abiertas (${openContracts.length})`}
          </span>
        </button>
        <button
          type="button"
          data-testid="tab-portfolio-cerradas"
          onClick={() => setActiveTab('cerradas')}
          style={{
            background: 'transparent',
            border: 'none',
            borderBottom: activeTab === 'cerradas' ? '2px solid #FFFFFF' : '2px solid transparent',
            color: activeTab === 'cerradas' ? '#FFFFFF' : '#8A92A1',
            padding: '8px 16px 10px 16px',
            fontSize: '13px',
            fontWeight: 700,
            cursor: 'pointer',
            transition: 'color 0.15s ease, border-color 0.15s ease',
            marginBottom: '-1px',
          }}
        >
          Cerradas
        </button>
      </div>

      {/* Conteúdo: Lista ou Estado Vazio */}
      {displayedContracts.length === 0 ? (
        <div
          data-testid="portfolio-empty-state"
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '60px 16px',
            textAlign: 'center',
          }}
        >
          {/* Ícone de Pasta Aberta */}
          <div
            style={{
              width: '56px',
              height: '56px',
              borderRadius: '12px',
              background: 'rgba(244, 245, 247, 0.04)',
              border: '1px solid rgba(244, 245, 247, 0.08)',
              display: 'grid',
              placeItems: 'center',
              marginBottom: '16px',
              color: '#8A92A1',
            }}
          >
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
            </svg>
          </div>
          <h3
            data-testid="portfolio-empty-title"
            style={{ fontSize: '14px', fontWeight: 800, color: '#F4F5F7', margin: '0 0 6px' }}
          >
            {activeTab === 'abiertas' ? 'No tienes operaciones abiertas' : 'No tienes operaciones cerradas'}
          </h3>
          <p
            data-testid="portfolio-empty-subtitle"
            style={{ fontSize: '11.5px', color: '#8A92A1', margin: 0, lineHeight: 1.4 }}
          >
            {activeTab === 'abiertas'
              ? 'Abre una operación con SUBE o BAJA.'
              : 'Tus operaciones finalizadas aparecerán aquí.'}
          </p>
        </div>
      ) : (
        /* Lista de Operações (Abertas ou Fechadas) */
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {displayedContracts.map((c) => {
            const isUp = c.direction === 'UP';
            const stake = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
            const stakeDollars = Math.round(stake / 100);

            const cleanSym = c.symbol.replace('_OTC', '').replace(/([A-Z]{3})([A-Z]{3})/, '$1/$2');

            // ─── ABA ABERTAS ──────────────────────────────────────────
            if (activeTab === 'abiertas') {
              const strikePrice = Number(c.strike_price ?? c.entry_price ?? 0);
              const numCurrentPrice = currentPrice !== null && currentPrice !== undefined ? Number(currentPrice) : null;
              let isWinning = false;
              if (numCurrentPrice !== null && Number.isFinite(numCurrentPrice)) {
                isWinning = isUp ? numCurrentPrice > strikePrice : numCurrentPrice < strikePrice;
              }

              const pnlDollars = isWinning ? (stakeDollars * 0.85).toFixed(2) : Number(stakeDollars).toFixed(2);
              const pnlFormatted = isWinning ? `+$${pnlDollars}` : `-$${pnlDollars}`;

              // Cálculos de Tempo e Progresso
              const createdMs = c.created_at ? new Date(c.created_at).getTime() : 0;
              const expiresMs = c.expires_at ? new Date(c.expires_at).getTime() : 0;
              const totalMs = Math.max(1000, expiresMs - createdMs);
              const elapsedMs = Math.max(0, now - createdMs);
              const progressPercent = Math.min(100, Math.max(0, (elapsedMs / totalMs) * 100));

              const remainingSec = Math.max(0, Math.floor((expiresMs - now) / 1000));
              const timerMins = Math.floor(remainingSec / 60);
              const timerSecs = remainingSec % 60;
              const timerText = `${String(timerMins).padStart(2, '0')}:${String(timerSecs).padStart(2, '0')}`;

              const expiryTimeStr = c.expires_at
                ? new Date(c.expires_at).toLocaleTimeString('es-ES', {
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit',
                    hour12: false,
                  })
                : '';

              return (
                <div
                  key={c.id}
                  data-testid={`portfolio-card-${c.id}`}
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '10px',
                    padding: '12px 14px',
                    background: '#171F2B',
                    border: '1px solid rgba(255, 255, 255, 0.07)',
