                      <AssetFlagBadge symbol={c.symbol} size={20} />
                      <strong style={{ fontSize: '13px', color: '#FFFFFF', fontWeight: 700, letterSpacing: '0.2px' }}>
                        {cleanSym}
                      </strong>
                      <span
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '2px',
                          fontSize: '9.5px',
                          fontWeight: 800,
                          padding: '2px 6px',
                          borderRadius: '3px',
                          background: isUp ? '#22C55E' : '#E5484D',
                          color: '#FFFFFF',
                          letterSpacing: '0.02em',
                          lineHeight: 1,
                        }}
                      >
                        <span>{isUp ? '↑ ARRIBA' : '↓ ABAJO'}</span>
                        <span style={{ display: 'none' }} aria-hidden="true">
                          {isUp ? 'SUBE' : 'BAJA'}
                        </span>
                      </span>
                    </div>

                    <strong
                      data-testid={`portfolio-pnl-${c.id}`}
                      style={{
                        fontSize: '14px',
                        color: isWinning ? '#22C55E' : '#E5484D',
                        fontFamily: "'Geist Mono', monospace",
                        fontWeight: 700,
                        letterSpacing: '0.2px',
                      }}
                    >
                      {pnlFormatted}
                    </strong>
                  </div>

                  {/* Linha 2: Invertido $X + Barra de Progresso + Timer mm:ss + Expira HH:mm:ss */}
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px' }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', minWidth: '55px' }}>
                      <span style={{ fontSize: '10.5px', color: '#8A92A1', fontWeight: 500, lineHeight: 1 }}>
                        Invertido
                      </span>
                      <strong style={{ fontSize: '13px', color: '#FFFFFF', fontFamily: "'Geist Mono', monospace", fontWeight: 700, lineHeight: 1.2 }}>
                        {`$${stakeDollars}`}
                      </strong>
                    </div>

                    <div style={{ display: 'flex', alignItems: 'center', flex: 1, gap: '10px' }}>
                      {/* Trilho e preenchimento da barra de progresso */}
                      <div
                        data-testid={`portfolio-progress-track-${c.id}`}
                        style={{
                          flex: 1,
                          height: '3px',
                          background: 'rgba(255, 255, 255, 0.12)',
                          borderRadius: '2px',
                          overflow: 'hidden',
                          position: 'relative',
                        }}
                      >
                        <div
                          data-testid={`portfolio-progress-bar-${c.id}`}
                          style={{
                            height: '100%',
                            width: `${progressPercent}%`,
                            background: isWinning ? '#22C55E' : '#E0E0E0',
                            borderRadius: '2px',
                            transition: 'width 0.3s linear',
                          }}
                        />
                      </div>

                      {/* Cronômetro e carimbo de expiração */}
                      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', minWidth: '45px' }}>
                        <span
                          data-testid={`portfolio-timer-${c.id}`}
                          style={{
                            fontSize: '12.5px',
                            fontWeight: 700,
                            color: '#FFFFFF',
                            fontFamily: "'Geist Mono', monospace",
                            lineHeight: 1,
                          }}
                        >
                          {timerText}
                        </span>
                        {expiryTimeStr && (
                          <span
                            data-testid={`portfolio-expiry-time-${c.id}`}
                            style={{
                              fontSize: '9.5px',
                              color: '#8A92A1',
                              fontFamily: "'Geist Mono', monospace",
                              marginTop: '3px',
                              lineHeight: 1,
                            }}
                          >
                            {`Expira ${expiryTimeStr}`}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            }

            // ─── ABA CERRADAS ─────────────────────────────────────────
            const isWin = c.result === 'WIN';
            const payout = typeof c.payout_minor === 'string' ? parseInt(c.payout_minor, 10) : (c.payout_minor ?? 0);
            const profitDollars = isWin ? ((payout - stake) / 100).toFixed(2) : Number(stakeDollars).toFixed(2);
            const closedPnlFormatted = isWin ? `+$${profitDollars}` : `-$${profitDollars}`;

            const closedTimeStr = c.expires_at
              ? new Date(c.expires_at).toLocaleTimeString('es-ES', {
                  hour: '2-digit',
                  minute: '2-digit',
                  second: '2-digit',
                  hour12: false,
                })
              : '';

            return (
              <div
                key={c.id}
                data-testid={`portfolio-card-${c.id}`}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '8px',
                  padding: '11px 13px',
                  background: '#171F2B',
                  border: '1px solid rgba(255, 255, 255, 0.07)',
                  borderRadius: '8px',
                  boxSizing: 'border-box',
                }}
              >
                {/* Linha 1: Bandeiras + Ativo + Badge Direção + Resultado Consolidado */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <AssetFlagBadge symbol={c.symbol} size={18} />
                    <strong style={{ fontSize: '12.5px', color: '#FFFFFF', fontWeight: 700 }}>
                      {cleanSym}
                    </strong>
                    <span
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '2px',
                        fontSize: '9px',
                        fontWeight: 800,
                        padding: '1px 5px',
                        borderRadius: '3px',
                        background: isUp ? '#22C55E' : '#E5484D',
                        color: '#FFFFFF',
                        lineHeight: 1,
                      }}
                    >
                      {isUp ? '↑ ARRIBA' : '↓ ABAJO'}
                    </span>
                  </div>

                  <strong
                    data-testid={`portfolio-pnl-${c.id}`}
                    style={{
                      fontSize: '13.5px',
                      color: isWin ? '#22C55E' : '#E5484D',
                      fontFamily: "'Geist Mono', monospace",
                      fontWeight: 700,
                    }}
                  >
                    {closedPnlFormatted}
                  </strong>
                </div>

                {/* Linha 2: Invertido $X + Status e Horário de Encerramento */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '10px', color: '#8A92A1', fontFamily: "'Geist Mono', monospace" }}>
                    {`Invertido $${stakeDollars}`}
                  </span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <span
                      style={{
                        fontSize: '9px',
                        fontWeight: 700,
                        padding: '1px 5px',
                        borderRadius: '3px',
                        background: isWin ? 'rgba(34, 197, 94, 0.15)' : 'rgba(229, 72, 77, 0.15)',
                        color: isWin ? '#22C55E' : '#E5484D',
                      }}
                    >
                      {isWin ? 'Ganada' : 'Perdida'}
                    </span>
                    {closedTimeStr && (
                      <span style={{ fontSize: '9.5px', color: '#8A92A1', fontFamily: "'Geist Mono', monospace" }}>
                        {closedTimeStr}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import { useEffect, useState } from 'react';
import type { Contract } from '../../api/client';
import { formatMinor, formatCurrencyBinmax } from '../../lib/money';
import { isNewTraderoomEnabled } from '../../lib/feature-flags';
import { getTabDisplayTitle } from '../header/TerminalHeader';

export interface PortfolioDrawerProps {
  isOpen: boolean;
  onToggle: () => void;
  contracts: Contract[];
  currentPrice: number | string | null;
  currentSymbol: string;
}

export function PortfolioDrawer({
  isOpen,
  onToggle,
  contracts,
  currentPrice,
  currentSymbol,
}: PortfolioDrawerProps) {
  const [tab, setTab] = useState<'ACTIVE' | 'HISTORY'>('ACTIVE');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(timer);
  }, []);

  const openContracts = contracts.filter((c) => c.status === 'OPEN');
  const settledContracts = contracts.filter((c) => c.status !== 'OPEN');

  // Calcular PnL total potencial
  const potentialPnlMinor = openContracts.reduce((acc, c) => {
    const stake = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
    return acc + Math.round(stake * 0.85);
  }, 0);

  const isBinmax = isNewTraderoomEnabled();

  return (
    <div
      className="portfolio-drawer-wrap"
      style={{
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        background: isBinmax ? '#151922' : '#0a101f',
        borderTop: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #1a253a',
        boxSizing: 'border-box',
      }}
    >
      {/* Barra de Rodapé Fixa (~30px) */}
      <div
        className="terminal-drawer-bar"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0 16px',
          height: '30px',
          fontSize: '11px',
          color: isBinmax ? '#8A92A1' : '#8e9db7',
          cursor: 'pointer',
          userSelect: 'none',
        }}
        onClick={onToggle}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span>💼</span>
            {!isBinmax && <strong style={{ color: '#fff' }}>Portfólio Total</strong>}
            <span
              style={{
                background: openContracts.length > 0 ? (isBinmax ? '#22C55E' : '#00e676') : (isBinmax ? '#0D0F14' : '#1c2d4a'),
                color: openContracts.length > 0 ? '#0D0F14' : '#8A92A1',
                borderRadius: '10px',
                padding: '1px 7px',
                fontSize: '10px',
                fontWeight: 800,
              }}
            >
              {`${openContracts.length} ${isBinmax ? 'activas' : 'ativas'}`}
            </span>
          </div>

          {openContracts.length > 0 && (
            <span style={{ color: isBinmax ? '#22C55E' : '#00e676', fontWeight: 600 }}>
              {isBinmax ? 'Ganancia potencial' : 'Retorno potencial'}: {`+${isBinmax ? formatCurrencyBinmax(potentialPnlMinor) : formatMinor(potentialPnlMinor)}`}
            </span>
          )}
        </div>

        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onToggle();
          }}
          style={{
            background: isBinmax ? '#0D0F14' : '#131e33',
            border: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #253450',
            color: isBinmax ? '#DCE1EA' : '#bcd0ec',
            borderRadius: '4px',
            padding: '2px 10px',
            fontSize: '11px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
          }}
        >
          {isBinmax
            ? (isOpen ? 'Mostrar posiciones ⌃' : 'Mostrar posiciones ⌵')
            : (isOpen ? '▼ Ocultar Painel' : `▲ Expandir (${openContracts.length})`)}
        </button>
      </div>

      {/* Conteúdo Expandido da Gaveta (220px) */}
      {isOpen && (
        <div
          style={{
            height: '220px',
            maxHeight: '220px',
            background: '#090f1d',
            borderTop: '1px solid #162238',
            display: 'flex',
            flexDirection: 'column',
            boxSizing: 'border-box',
          }}
        >
          {/* Sub-abas da gaveta */}
          <div
            style={{
              display: 'flex',
              gap: '6px',
              padding: '8px 16px',
              borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #162238',
              background: isBinmax ? '#0D0F14' : '#070c18',
            }}
          >
            <button
              type="button"
              onClick={() => setTab('ACTIVE')}
              style={{
                background: tab === 'ACTIVE' ? (isBinmax ? 'rgba(34, 197, 94, 0.15)' : '#192b49') : 'transparent',
                border: tab === 'ACTIVE' ? (isBinmax ? '1px solid #22C55E' : '1px solid #273e66') : '1px solid transparent',
                color: tab === 'ACTIVE' ? (isBinmax ? '#22C55E' : '#00e676') : '#8A92A1',
                borderRadius: '6px',
                padding: '4px 12px',
                fontSize: '11px',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {isBinmax ? `Operaciones abiertas (${openContracts.length})` : `Operações Abertas (${openContracts.length})`}
            </button>
            <button
              type="button"
              onClick={() => setTab('HISTORY')}
              style={{
                background: tab === 'HISTORY' ? (isBinmax ? 'rgba(34, 197, 94, 0.15)' : '#192b49') : 'transparent',
                border: tab === 'HISTORY' ? (isBinmax ? '1px solid #22C55E' : '1px solid #273e66') : '1px solid transparent',
                color: tab === 'HISTORY' ? (isBinmax ? '#22C55E' : '#00e676') : '#8A92A1',
                borderRadius: '6px',
                padding: '4px 12px',
                fontSize: '11px',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {isBinmax ? `Historial cerrado (${settledContracts.length})` : `Histórico Finalizado (${settledContracts.length})`}
            </button>
          </div>

          {/* Tabela de Operações */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '0 16px' }}>
            {tab === 'ACTIVE' ? (
              openContracts.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '40px 0', color: '#8A92A1', fontSize: '12px' }}>
                  {isBinmax
                    ? 'Aún no tienes operaciones abiertas. Elige SUBE o BAJA para empezar.'
                    : 'Nenhuma ordem em andamento. Abra uma posição ACIMA ou ABAIXO para acompanhar ao vivo aqui.'}
                </div>
              ) : (
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px', textAlign: 'left' }}>
                  <thead>
                    <tr style={{ color: '#8A92A1', borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #1a273e' }}>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Activo' : 'ID / Ativo'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Dirección' : 'Direção'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Inversión' : 'Valor'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Tiempo restante' : 'Expiração'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Estado' : 'Status'}</th>
                      <th style={{ padding: '8px 6px', textAlign: 'right' }}>{isBinmax ? 'Ganancia potencial' : 'Retorno Potencial'}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {openContracts.map((c) => {
                      const stakeNum = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
                      const expEpoch = Date.parse(c.expires_at);
                      const secondsLeft = Math.max(0, Math.ceil((expEpoch - now) / 1000));
                      const progressPct = Math.min(100, Math.max(0, ((60 - secondsLeft) / 60) * 100));

                      return (
                        <tr key={c.id} style={{ borderBottom: '1px solid #141f33', color: '#e0e9f6' }}>
                          <td style={{ padding: '8px 6px' }}>
                            <strong style={{ color: '#fff' }}>{isBinmax ? getTabDisplayTitle(c.symbol) : c.symbol}</strong>
                            <div style={{ fontSize: '10px', color: '#687b99' }}>#{c.id.slice(0, 8)}</div>
                          </td>
                          <td style={{ padding: '8px 6px' }}>
                            <span
                              style={{
                                color: c.direction === 'UP' ? (isBinmax ? '#22C55E' : '#00e676') : (isBinmax ? '#E5484D' : '#ff3d71'),
                                fontWeight: 700,
                              }}
                            >
                              {isBinmax
                                ? (c.direction === 'UP' ? '▲ SUBE' : '▼ BAJA')
                                : (c.direction === 'UP' ? '▲ ACIMA' : '▼ ABAIXO')}
                            </span>
                          </td>
                          <td style={{ padding: '8px 6px', fontFamily: isBinmax ? "'Geist Mono', monospace" : 'inherit' }}>
                            {isBinmax ? formatCurrencyBinmax(stakeNum) : formatMinor(stakeNum)}
                          </td>
                          <td style={{ padding: '8px 6px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                              <span style={{ fontFamily: isBinmax ? "'Geist Mono', monospace" : 'inherit' }}>{secondsLeft}s</span>
                              <div
                                style={{
                                  width: '60px',
                                  height: '4px',
                                  background: isBinmax ? '#0D0F14' : '#192b49',
                                  borderRadius: '2px',
                                  overflow: 'hidden',
                                }}
                              >
                                <div
                                  style={{
                                    height: '100%',
                                    width: `${progressPct}%`,
                                    background: isBinmax ? '#22C55E' : '#00e676',
                                  }}
                                />
                              </div>
                            </div>
                          </td>
                          <td style={{ padding: '8px 6px' }}>
                            <span style={{ color: isBinmax ? '#DCE1EA' : '#65d5ff', fontWeight: 600 }}>
                              {isBinmax ? 'En curso' : 'Em andamento'}
                            </span>
                          </td>
                          <td style={{ padding: '8px 6px', textAlign: 'right' }}>
                            <strong style={{ color: isBinmax ? '#22C55E' : '#00e676', fontFamily: isBinmax ? "'Geist Mono', monospace" : "'Space Grotesk', sans-serif" }}>
                              {`+${isBinmax ? formatCurrencyBinmax(Math.round(stakeNum * 0.85)) : formatMinor(Math.round(stakeNum * 0.85))}`}
                            </strong>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )
            ) : settledContracts.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '40px 0', color: '#8A92A1', fontSize: '12px' }}>
                {isBinmax ? 'Aún no tienes operaciones cerradas.' : 'Nenhum histórico disponível ainda.'}
              </div>
            ) : (
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px', textAlign: 'left' }}>
                <thead>
                  <tr style={{ color: '#8A92A1', borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #1a273e' }}>
                    <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Activo' : 'ID / Ativo'}</th>
                    <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Dirección' : 'Direção'}</th>
                    <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Inversión' : 'Investido'}</th>
                    <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Resultado' : 'Resultado'}</th>
                    <th style={{ padding: '8px 6px', textAlign: 'right' }}>{isBinmax ? 'Retorno' : 'Retorno'}</th>
                  </tr>
                </thead>
                <tbody>
                  {settledContracts.slice(0, 20).map((c) => {
                    const stakeNum = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
                    const payoutNum = c.payout_minor !== null ? (typeof c.payout_minor === 'string' ? parseInt(c.payout_minor, 10) : c.payout_minor) : 0;
                    const isWin = c.result === 'WIN';
                    const isDraw = c.result === 'DRAW';

                    return (
                      <tr key={c.id} style={{ borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.04)' : '1px solid #141f33', color: '#e0e9f6' }}>
                        <td style={{ padding: '8px 6px' }}>
                          <strong style={{ color: '#fff' }}>{isBinmax ? getTabDisplayTitle(c.symbol) : c.symbol}</strong>
                          <div style={{ fontSize: '10px', color: '#8A92A1' }}>#{c.id.slice(0, 8)}</div>
                        </td>
                        <td style={{ padding: '8px 6px' }}>
                          <span style={{ color: c.direction === 'UP' ? (isBinmax ? '#22C55E' : '#00e676') : (isBinmax ? '#E5484D' : '#ff3d71'), fontWeight: 700 }}>
                            {isBinmax
                              ? (c.direction === 'UP' ? '▲ SUBE' : '▼ BAJA')
                              : (c.direction === 'UP' ? '▲ ALTA' : '▼ BAIXA')}
                          </span>
                        </td>
                        <td style={{ padding: '8px 6px', fontFamily: isBinmax ? "'Geist Mono', monospace" : 'inherit' }}>
                          {isBinmax ? formatCurrencyBinmax(stakeNum) : formatMinor(stakeNum)}
                        </td>
                        <td style={{ padding: '8px 6px' }}>
                          <span
                            style={{
                              padding: '2px 8px',
                              borderRadius: '4px',
                              fontSize: '11px',
                              fontWeight: 800,
                              background: isWin
                                ? (isBinmax ? 'rgba(34, 197, 94, 0.15)' : 'rgba(0, 230, 118, 0.15)')
                                : isDraw
                                ? 'rgba(255, 171, 0, 0.15)'
                                : (isBinmax ? 'rgba(229, 72, 77, 0.15)' : 'rgba(255, 61, 113, 0.15)'),
                              color: isWin
                                ? (isBinmax ? '#22C55E' : '#00e676')
                                : isDraw
                                ? '#ffab00'
                                : (isBinmax ? '#E5484D' : '#ff3d71'),
                            }}
                          >
                            {isWin ? (isBinmax ? 'GANADA' : 'VITÓRIA') : isDraw ? (isBinmax ? 'EMPATE' : 'EMPATE') : (isBinmax ? 'PERDIDA' : 'DERROTA')}
                          </span>
                        </td>
                        <td style={{ padding: '8px 6px', textAlign: 'right' }}>
                          <strong
                            style={{
                              color: isWin
                                ? (isBinmax ? '#22C55E' : '#00e676')
                                : isDraw
                                ? '#ffab00'
                                : (isBinmax ? '#E5484D' : '#ff3d71'),
                              fontFamily: isBinmax ? "'Geist Mono', monospace" : "'Space Grotesk', sans-serif",
                            }}
                          >
                            {isWin
                              ? `+${isBinmax ? formatCurrencyBinmax(payoutNum) : formatMinor(payoutNum)}`
                              : isDraw
                              ? (isBinmax ? formatCurrencyBinmax(payoutNum) : formatMinor(payoutNum))
                              : `−${isBinmax ? formatCurrencyBinmax(stakeNum) : formatMinor(stakeNum)}`}
                          </strong>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

