              </div>

              {/* Botão Criar Conta */}
              <button
                type="submit"
                disabled={isLoading}
                style={{
                  width: '100%',
                  backgroundColor: '#22C55E',
                  color: '#08140B',
                  fontWeight: 700,
                  fontSize: '15px',
                  padding: '13px',
                  borderRadius: '6px',
                  border: 'none',
                  cursor: isLoading ? 'not-allowed' : 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '8px',
                  boxShadow: '0 4px 14px rgba(34, 197, 94, 0.3)',
                  marginBottom: '20px',
                }}
              >
                <span>Crear cuenta de práctica</span>
                <span>→</span>
              </button>

              {/* Card de Boas-Vindas $10.000 */}
              <div
                style={{
                  backgroundColor: '#0B1220',
                  border: '1px solid #1F2A3A',
                  borderRadius: '6px',
                  padding: '12px 14px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '12px',
