                <div style={{ fontSize: '20px' }}>🎁</div>
                <div style={{ fontSize: '12px', color: '#8A96A8', lineHeight: 1.4 }}>
                  Entrarás directamente a la sala de trading con <strong style={{ color: '#22C55E' }}>$10.000</strong> en modo práctica y un recorrido guiado para tu primera vez.
                </div>
              </div>
            </form>

            <div
              style={{
                marginTop: '28px',
                paddingTop: '16px',
                borderTop: '1px solid #1F2A3A',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                fontSize: '12px',
                color: '#64748B',
              }}
            >
              <div>ES | PT</div>
              <div style={{ display: 'flex', gap: '12px' }}>
                <a href="#terminos" style={{ color: '#64748B', textDecoration: 'none' }}>Términos</a>
                <a href="#privacidad" style={{ color: '#64748B', textDecoration: 'none' }}>Privacidad</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

