                    </span>
                  </div>

                  <h3 style={{ fontSize: '15.5px', fontWeight: 700, color: PRECISION_TEXT.strong, margin: '0 0 12px' }}>
                    {t.name}
                  </h3>

                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: '16px' }}>
