        </div>

        {/* ─── DETALHES DO EVENTO & AUDITORIA DE RANKING ───────────────── */}
        <div
          data-testid="tournament-details-panel"
          style={{
            backgroundColor: PRECISION_SURFACES.bg1,
            border: `1px solid ${PRECISION_SURFACES.line}`,
            borderRadius: '8px',
            padding: '24px',
