                    gap: '4px',
                  }}
                >
                  <IconCheckCircle size={13} /> Aprobado
                </span>
                <div className="bm-tabular-nums" style={{ fontSize: '11px', color: '#64748B', marginTop: '4px' }}>
                  09 oct. 2026, 18:20
