              </div>
            </div>

            {/* PASSO 2: IDENTIDAD (PROTAGONISTA DA TELA) */}
            <div
              style={{
                backgroundColor: PRECISION_SURFACES.panel,
                border: `1px solid ${PRECISION_COLORS.borderSubtle}`,
                borderRadius: '8px',
                padding: '24px',
              }}
            >
              {/* Cabeçalho do Passo 2 */}
              <div
                style={{
                  display: 'flex',
