                      Formatos: JPG, PNG o PDF (máx. 15 MB por archivo)
                    </div>
                  </label>

                  {/* ESTADO CARREGANDO / PROGRESSO REAL */}
                  {uploadProgress !== null && (
                    <div style={{ marginTop: '10px' }}>
                      <div
                        style={{
                          height: '4px',
                          backgroundColor: 'rgba(255, 255, 255, 0.08)',
