  const [error, setError] = useState('');
  const [receipt, setReceipt] = useState<Receipt | null>(null);
  const [now, setNow] = useState(Date.now());
  const [selectedSlotId, setSelectedSlotId] = useState<string>('candle_1m');
  const [selectedSlot, setSelectedSlot] = useState<ExpirySlot | null>(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const intent = useRef<{ key: string; direction: 'UP' | 'DOWN'; stakeMinor: number } | null>(null);
  const notified = useRef<string | null>(null);
  const executingRef = useRef(false);
  const slots = calculateExpirySlots(new Date(), -3);
  const activeSlot = slots.find((s) => s.id === selectedSlotId) ?? slots[0];

  const navigateSlot = (direction: 1 | -1) => {
    soundEngine.playClick();
    const currentIndex = slots.findIndex((s) => s.id === selectedSlotId);
    const nextIndex = Math.max(0, Math.min(slots.length - 1, currentIndex + direction));
    const target = slots[nextIndex];
    if (target) {
      setSelectedSlotId(target.id);
      setSelectedSlot(target);
    }
  };

  const contract = useQuery({
    queryKey: ['contract', receipt?.id],
    queryFn: () => getContract(receipt!.id),
    enabled: Boolean(receipt?.id),
    refetchInterval: (query) =>
      ['SETTLED', 'FAILED_COMPENSATION', 'CANCELLED'].includes(query.state.data?.status ?? '')
        ? false
        : 1000,
  });

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 250);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    soundEngine.setMuted(!soundEnabled);
  }, [soundEnabled]);

  useEffect(() => {
    const value = contract.data;
    if (value && ['SETTLED', 'FAILED_COMPENSATION', 'CANCELLED'].includes(value.status) && notified.current !== value.id) {
      notified.current = value.id;
      if (value.result === 'WIN') soundEngine.playWin();
      else if (value.result === 'LOSS') soundEngine.playLoss();
      else if (value.result === 'DRAW') soundEngine.playDraw();
      onChanged();
    }
  }, [contract.data, onChanged]);

  const stakeMinor = parseStakeInput(stake);

  // Contagem regressiva da vela atual (ciclo de 60 segundos)
  const secondsInMinute = Math.floor(now / 1000) % 60;
  const candleRemaining = 60 - secondsInMinute;
  const isLocked30s = false;

  const remainingReceipt = receipt
    ? Math.max(0, Math.ceil((Date.parse(receipt.expires_at) - now) / 1000))
    : 0;

  const currentAvailable = availableMinor ?? 1000000;
  const blocked =
    paused ||
    stale ||
    stakeMinor === null ||
    stakeMinor > currentAvailable;

  const assetMeta = getAssetMeta(symbol);
  const payoutPct = assetMeta.payout;
  const payoutProfitMinor = stakeMinor !== null ? Math.round(stakeMinor * (payoutPct / 100)) : 850;
  const totalReturnMinor = (stakeMinor ?? 1000) + payoutProfitMinor;

  const adjustStake = (delta: number) => {
    soundEngine.playClick();
    const current = stakeMinor !== null ? stakeMinor : 1000;
    const next = Math.max(100, Math.min(10000, current + delta));
    if (next % 100 === 0) {
      setStake(String(next / 100));
    } else {
      setStake((next / 100).toFixed(2).replace('.', ','));
    }
  };

  const setPreset = (valueUsd: number) => {
    soundEngine.playClick();
    setStake(valueUsd.toFixed(2).replace('.', ','));
  };

  async function handleExecute(direction: 'UP' | 'DOWN') {
    if (executingRef.current || blocked || busy || stakeMinor === null) return;
    executingRef.current = true;
    setBusy(true);
    setError('');
    soundEngine.playOrderOpen();

    try {
      const key = safeRandomUUID();
      const current = { key, direction, stakeMinor };
      intent.current = current;
      const mode: ExpiryMode = selectedSlot?.mode ?? '1M_FIXED';
      const { durationMs, targetEpochMs } = calculateExecutionExpiry(mode, Date.now());
      const durationSeconds = Math.max(30, Math.round(durationMs / 1000));
      const targetExpiresAt = new Date(targetEpochMs).toISOString();

      const opened = await openContract(
        symbol,
        current.direction,
        current.stakeMinor,
        current.key,
        durationSeconds,
        targetExpiresAt,
        mode
      );
      setReceipt(opened);
      intent.current = null;
      onChanged();
    } catch (cause) {
      if (cause instanceof ApiError) {
        setError(messages[cause.code] ?? 'Não foi possível enviar a ordem.');
        if (cause.status < 500 && cause.status !== 429) intent.current = null;
        if (cause.code === 'INDEX_PAUSED') onChanged();
      } else {
        setError(cause instanceof Error ? cause.message : 'Falha ao processar ordem. Tente novamente.');
      }
    } finally {
      executingRef.current = false;
      setBusy(false);
    }
  }

  // Atalhos de teclado seguros com supressão sob feed stale ou bloqueio (Passo 5.5)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) return;
      if (blocked || busy || stakeMinor === null) return;

      if (e.key === 'ArrowUp' || e.key.toLowerCase() === 'u') {
        e.preventDefault();
        handleExecute('UP');
      } else if (e.key === 'ArrowDown' || e.key.toLowerCase() === 'd') {
        e.preventDefault();
        handleExecute('DOWN');
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [blocked, busy, stakeMinor]);

  if (isBinmax) {
    const formattedExpiryDisplay = activeSlot
      ? formatSecondsToMmSs(activeSlot.remainingSeconds)
      : '00:21';

    return (
      <div
        className="order-dock-container binmax-order-dock"
        data-testid="binmax-order-ticket"
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          width: '100%',
          color: '#F4F5F7',
          boxSizing: 'border-box',
        }}
      >
        {/* D1: MONTO */}
        <div className="binmax-ticket-block" data-testid="ticket-block-monto">
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: '4px',
            }}
          >
            <span style={{ fontSize: '12px', color: '#8A92A1', fontWeight: 500, fontFamily: "'Inter', sans-serif" }}>
              Monto
            </span>
            <span
              aria-label="Ayuda monto"
              style={{
                fontSize: '9px',
                color: '#8A92A1',
                cursor: 'pointer',
                width: '13px',
                height: '13px',
                borderRadius: '50%',
                border: '1px solid rgba(138, 146, 161, 0.4)',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                lineHeight: 1,
              }}
            >
              ?
            </span>
          </div>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              background: '#151922',
              border: '1px solid rgba(244, 245, 247, 0.08)',
              borderRadius: '6px',
              height: '34px',
              boxSizing: 'border-box',
              overflow: 'hidden',
            }}
          >
            <button
              type="button"
              aria-label="Disminuir monto"
              onClick={() => adjustStake(-100)}
              style={{
                width: '28px',
                height: '100%',
                background: 'rgba(255, 255, 255, 0.03)',
                border: 'none',
                borderRight: '1px solid rgba(244, 245, 247, 0.06)',
                color: '#8A92A1',
                fontSize: '15px',
                fontWeight: 600,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 0,
                lineHeight: 1,
              }}
            >
              −
            </button>

            <div
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                minWidth: 0,
                padding: '0 2px',
              }}
            >
              <span style={{ color: '#DCE1EA', fontSize: '12px', fontWeight: 600, marginRight: '3px' }}>
                $
              </span>
              <input
                id="binmax-stake-input"
                aria-label="Monto de la inversión"
                inputMode="decimal"
                value={stake}
                onChange={(e) => setStake(e.target.value)}
                style={{
                  width: '42px',
                  background: 'none',
                  border: 'none',
                  outline: 'none',
                  color: '#F4F5F7',
                  fontSize: '13px',
                  fontWeight: 700,
                  fontFamily: "'Geist Mono', monospace",
                  textAlign: 'center',
                }}
              />
            </div>

            <button
              type="button"
              aria-label="Aumentar monto"
              onClick={() => adjustStake(100)}
              style={{
                width: '28px',
                height: '100%',
                background: 'rgba(255, 255, 255, 0.03)',
                border: 'none',
                borderLeft: '1px solid rgba(244, 245, 247, 0.06)',
                color: '#8A92A1',
                fontSize: '15px',
                fontWeight: 600,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 0,
                lineHeight: 1,
              }}
            >
              +
            </button>
          </div>
        </div>

        {/* D2: EXPIRACIÓN */}
        <div className="binmax-ticket-block" data-testid="ticket-block-expiracion" style={{ position: 'relative' }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: '4px',
            }}
          >
            <span style={{ fontSize: '12px', color: '#8A92A1', fontWeight: 500, fontFamily: "'Inter', sans-serif" }}>
              Expiración
            </span>
            <span
              aria-label="Ayuda expiración"
              style={{
                fontSize: '9px',
                color: '#8A92A1',
                cursor: 'pointer',
                width: '13px',
                height: '13px',
                borderRadius: '50%',
                border: '1px solid rgba(138, 146, 161, 0.4)',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                lineHeight: 1,
              }}
            >
              ?
            </span>
          </div>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              background: '#151922',
              border: '1px solid rgba(244, 245, 247, 0.08)',
              borderRadius: '6px',
              height: '34px',
              boxSizing: 'border-box',
              overflow: 'hidden',
            }}
          >
            <button
              type="button"
              aria-label="Anterior expiración"
              onClick={() => navigateSlot(-1)}
              style={{
                width: '28px',
                height: '100%',
                background: 'rgba(255, 255, 255, 0.03)',
                border: 'none',
                borderRight: '1px solid rgba(244, 245, 247, 0.06)',
                color: '#8A92A1',
                fontSize: '15px',
                fontWeight: 600,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 0,
                lineHeight: 1,
              }}
            >
              −
            </button>

            <div
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: 'pointer',
                gap: '4px',
                minWidth: 0,
              }}
              onClick={() => setDropdownOpen(!dropdownOpen)}
            >
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="#8A92A1"
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <circle cx="12" cy="12" r="10" />
                <polyline points="12 6 12 12 16 14" />
              </svg>
              <span
                style={{
                  color: '#F4F5F7',
                  fontSize: '13px',
                  fontWeight: 700,
                  fontFamily: "'Geist Mono', monospace",
                }}
              >
                {formattedExpiryDisplay}
              </span>
            </div>

            <button
              type="button"
              aria-label="Siguiente expiración"
              onClick={() => navigateSlot(1)}
              style={{
                width: '28px',
                height: '100%',
                background: 'rgba(255, 255, 255, 0.03)',
                border: 'none',
                borderLeft: '1px solid rgba(244, 245, 247, 0.06)',
                color: '#8A92A1',
                fontSize: '15px',
                fontWeight: 600,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 0,
                lineHeight: 1,
              }}
            >
              +
            </button>
          </div>

          {dropdownOpen && (
            <div
              data-testid="expiry-dropdown-menu"
              style={{
                position: 'absolute',
                top: '56px',
                right: 0,
                width: '180px',
                background: '#151922',
                border: '1px solid rgba(244, 245, 247, 0.15)',
                borderRadius: '8px',
                boxShadow: '0 8px 24px rgba(0,0,0,0.6)',
                zIndex: 100,
                padding: '6px',
                display: 'flex',
                flexDirection: 'column',
                gap: '4px',
              }}
            >
              {slots.map((s) => (
                <button
                  key={s.id}
                  type="button"
                  onClick={() => {
                    setSelectedSlotId(s.id);
                    setSelectedSlot(s);
                    setDropdownOpen(false);
                  }}
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    background: s.id === selectedSlotId ? 'rgba(34, 196, 122, 0.15)' : 'transparent',
                    border: s.id === selectedSlotId ? '1px solid #22C47A' : 'none',
                    borderRadius: '6px',
                    padding: '6px 8px',
                    color: s.id === selectedSlotId ? '#22C47A' : '#F4F5F7',
                    cursor: 'pointer',
                    fontSize: '11px',
                    textAlign: 'left',
                  }}
                >
                  <span>{s.label}</span>
                  <span style={{ fontFamily: "'Geist Mono', monospace", fontWeight: 700 }}>
                    {s.targetTimeFormatted}
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* D3: GANANCIA */}
        <div
          className="binmax-ticket-block"
          data-testid="ticket-block-ganancia"
          style={{ textAlign: 'center', padding: '2px 0' }}
        >
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: '2px',
            }}
          >
            <span style={{ fontSize: '12px', color: '#8A92A1', fontWeight: 500, fontFamily: "'Inter', sans-serif" }}>
              Ganancia
            </span>
            <span
              aria-label="Ayuda ganancia"
              style={{
                fontSize: '9px',
                color: '#8A92A1',
                cursor: 'pointer',
                width: '13px',
                height: '13px',
                borderRadius: '50%',
                border: '1px solid rgba(138, 146, 161, 0.4)',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                lineHeight: 1,
              }}
            >
              ?
            </span>
          </div>

          <div
            data-testid="ganancia-pct"
            style={{
              fontSize: '22px',
              fontWeight: 800,
              lineHeight: '1.05',
              color: '#22C55E',
              fontFamily: "'Geist Mono', monospace",
              letterSpacing: '-0.3px',
            }}
          >
            {`+${payoutPct}%`}
          </div>

          <div
            data-testid="ganancia-amount"
            style={{
              fontSize: '13px',
              fontWeight: 700,
              color: '#22C55E',
              fontFamily: "'Geist Mono', monospace",
              marginTop: '1px',
            }}
          >
            {isBinmax ? `+${formatCurrencyBinmax(payoutProfitMinor)}` : `+${formatMinor(payoutProfitMinor)}`}
          </div>
        </div>

        {/* D4: SUBE */}
        <button
          type="button"
          data-testid="btn-sube"
          aria-label="Operación Sube"
          disabled={blocked || busy}
          onClick={() => handleExecute('UP')}
          style={{
            width: '100%',
            height: '52px',
            borderRadius: '6px',
            background: '#22C55E',
            border: 'none',
            color: '#FFFFFF',
            cursor: blocked || busy ? 'not-allowed' : 'pointer',
            opacity: blocked || busy ? 0.45 : 1,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '3px',
            padding: '6px 4px',
            boxSizing: 'border-box',
            boxShadow: blocked || busy ? 'none' : '0 2px 8px rgba(0, 0, 0, 0.25)',
            transition: 'transform 0.12s ease, opacity 0.12s ease, background 0.12s ease',
          }}
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#FFFFFF"
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
            data-testid="icon-sube"
          >
            <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" />
            <polyline points="16 7 22 7 22 13" />
          </svg>
          <span style={{ fontSize: '13px', fontWeight: 800, letterSpacing: '0.6px', color: '#FFFFFF' }}>
            SUBE
          </span>
        </button>

        {/* D5: BAJA */}
        <button
          type="button"
          data-testid="btn-baja"
          aria-label="Operación Baja"
          disabled={blocked || busy}
          onClick={() => handleExecute('DOWN')}
          style={{
            width: '100%',
            height: '52px',
            borderRadius: '6px',
            background: '#E5484D',
            border: 'none',
            color: '#FFFFFF',
            cursor: blocked || busy ? 'not-allowed' : 'pointer',
            opacity: blocked || busy ? 0.45 : 1,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '3px',
            padding: '6px 4px',
            boxSizing: 'border-box',
            boxShadow: blocked || busy ? 'none' : '0 2px 8px rgba(0, 0, 0, 0.25)',
            transition: 'transform 0.12s ease, opacity 0.12s ease, background 0.12s ease',
          }}
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#FFFFFF"
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
            data-testid="icon-baja"
          >
            <polyline points="22 17 13.5 8.5 8.5 13.5 2 7" />
            <polyline points="16 17 22 17 22 11" />
          </svg>
          <span style={{ fontSize: '13px', fontWeight: 800, letterSpacing: '0.6px', color: '#FFFFFF' }}>
            BAJA
          </span>
        </button>

        {/* Mensagens de Alerta ou Trava Compactas */}
        {paused && (
          <div
            data-testid="badge-paused"
            style={{
              background: '#3b2222',
              border: '1px solid #783535',
              borderRadius: '6px',
              padding: '6px',
              fontSize: '10px',
              color: '#ff9da5',
              textAlign: 'center',
            }}
          >
            Pausado
          </div>
        )}
        {stale && !paused && (
          <div
            data-testid="badge-stale"
            style={{
              background: '#3b2f22',
              border: '1px solid #785a35',
              borderRadius: '6px',
              padding: '6px',
              fontSize: '10px',
              color: '#ffc107',
              textAlign: 'center',
            }}
          >
            Atrasado
          </div>
        )}
        {error && (
          <div
            role="alert"
            data-testid="ticket-error"
            style={{
              background: '#3b2222',
              border: '1px solid #783535',
              borderRadius: '6px',
              padding: '6px',
              fontSize: '10px',
              color: '#ff9da5',
              textAlign: 'center',
            }}
          >
            {error}
          </div>
        )}

        {/* Resumo Discreto de Última Operação (Elimina Cartão Volumoso Duplicado) */}
        {receipt && contract.data?.status === 'SETTLED' && (
          <div
            style={{
              textAlign: 'center',
              fontSize: '11px',
              color: '#8A92A1',
              marginTop: '6px',
            }}
            aria-live="polite"
          >
            Última operación:{' '}
            <span
              style={{
                color: contract.data.result === 'WIN' ? '#22C55E' : contract.data.result === 'DRAW' ? '#ffab00' : '#E5484D',
                fontWeight: 700,
                fontFamily: "'Geist Mono', monospace",
              }}
            >
              {contract.data.result === 'WIN'
                ? `+${isBinmax ? formatCurrencyBinmax(contract.data.payout_minor ?? 0) : formatMinor(contract.data.payout_minor ?? 0)}`
                : contract.data.result === 'DRAW'
                ? (isBinmax ? formatCurrencyBinmax(contract.data.payout_minor ?? 0) : formatMinor(contract.data.payout_minor ?? 0))
                : `−${isBinmax ? formatCurrencyBinmax(stakeMinor ?? 1000) : formatMinor(stakeMinor ?? 1000)}`}
            </span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div
      className="order-dock-container"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        width: '100%',
        color: '#e8edf8',
        boxSizing: 'border-box',
      }}
    >
      {/* Card 0: Ativo Selecionado & Rendimento */}
      <div
        style={{
          background: '#101a2f',
          border: '1px solid #1f2e4b',
          borderRadius: '10px',
          padding: '10px 14px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span style={{ fontSize: '13px', fontWeight: 800, color: '#fff' }}>{symbol}</span>
            <span
              style={{
                fontSize: '9px',
                fontWeight: 700,
                padding: '1px 5px',
                borderRadius: '3px',
                background: 'rgba(59, 130, 246, 0.15)',
                color: '#60a5fa',
                border: '1px solid rgba(59, 130, 246, 0.3)',
              }}
            >
              {assetMeta.category}
            </span>
          </div>
          <small style={{ color: '#687b99', fontSize: '10px' }}>{assetMeta.name}</small>
        </div>
        <div style={{ textAlign: 'right' }}>
          <span style={{ fontSize: '9px', color: '#8898b8', display: 'block', fontWeight: 600 }}>
            LUCRO POTENCIAL
          </span>
          <span style={{ fontSize: '14px', fontWeight: 800, color: '#00e676' }}>
            +{payoutPct}%
          </span>
        </div>
      </div>
      {/* Card 1: Seletor de Tempo de Expiração Estilo IQ Option */}
      <ExpiryDropdown
        selectedSlotId={selectedSlotId}
        onSelectSlot={(slot) => {
          setSelectedSlotId(slot.id);
          setSelectedSlot(slot);
        }}
      />

      {/* Card 2: Valor do Investimento (Stake) com Steppers & Presets */}
      <div
        style={{
          background: '#101a2f',
          border: '1px solid #1f2e4b',
          borderRadius: '10px',
          padding: '12px 14px',
        }}
      >
        <label htmlFor="stake-input" style={{ fontSize: '11px', color: '#8898b8', fontWeight: 600, display: 'block', marginBottom: '8px' }}>
          VALOR DO INVESTIMENTO
        </label>

        {/* Stepper Input */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '10px' }}>
          <button
            type="button"
            onClick={() => adjustStake(-100)}
            style={{
              width: '36px',
