              )
            ) : remainingReceipt > 0 ? (
              <span style={{ color: '#65d5ff' }}>⏳ Expira em {remainingReceipt} segundos…</span>
            ) : (
              <span style={{ color: '#ffab00' }}>Processando liquidação oficial…</span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

