    const expirationYTop = 56;
    const expirationYBottom = 56 + 22; // 78px

    // Intervalo de Y: [24, 48] vs [56, 78]
    const verticalGap = expirationYTop - purchaseYBottom;
    expect(verticalGap).toBeGreaterThanOrEqual(8);
