    symbol: 'NZDJPY_OTC',
    paused: false,
    stale: false,
    availableMinor: 1000000, // $10,000.00
    soundEnabled: false,
    onChanged: vi.fn(),
    ...props,
  };

  return renderToString(
    <QueryClientProvider client={queryClient}>
      <OrderTicket {...defaultProps} />
    </QueryClientProvider>
  );
}

