export interface BinmaxWithdrawModalProps {
  isOpen: boolean;
  onClose: () => void;
  availableBalanceFormatted?: string;
  onWithdrawRequested?: (amount: number, address: string) => void;
}

export type WithdrawMethod = 'BANK' | 'PIX' | 'CRYPTO';

export function BinmaxWithdrawModal({
  isOpen,
  onClose,
  availableBalanceFormatted = es.withdraw_demo.unavailable,
  onWithdrawRequested,
}: BinmaxWithdrawModalProps) {
  const [method, setMethod] = useState<WithdrawMethod>('PIX');
  const [amount, setAmount] = useState<number>(100);
  const [address, setAddress] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const pending = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cancelPending = () => {
    if (timer.current !== null) clearTimeout(timer.current);
    timer.current = null;
    pending.current = false;
  };

  useEffect(() => {
    if (!isOpen) {
      setIsLoading(false);
      setSuccess(false);
      setErrorMsg('');
    }
    return cancelPending;
  }, [isOpen]);

  const handleClose = () => {
    cancelPending();
    setIsLoading(false);
    setSuccess(false);
    onClose();
  };

  if (!isOpen) return null;

  const handleWithdraw = (e: React.FormEvent) => {
    e.preventDefault();
    if (pending.current || isLoading || success) return;

    setErrorMsg('');

    if (amount < 50) {
      setErrorMsg('El monto mínimo de retiro es de $50.00');
      return;
    }

    if (!address.trim()) {
      setErrorMsg('Por favor, ingresa tu clave PIX, cuenta bancaria o dirección de cartera.');
      return;
    }

    pending.current = true;
    setIsLoading(true);

    timer.current = setTimeout(() => {
      timer.current = null;
      try {
        if (onWithdrawRequested) onWithdrawRequested(amount, address);
        setSuccess(true);
      } catch {
        setErrorMsg(es.withdraw_demo.failure);
      } finally {
        pending.current = false;
        setIsLoading(false);
      }
    }, 600);
  };

  return (
    <div
      data-testid="binmax-withdraw-modal"
      style={{
        position: 'fixed',
        inset: 0,
        backgroundColor: 'rgba(5, 10, 20, 0.65)',
        backdropFilter: 'blur(6px)',
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '16px',
        boxSizing: 'border-box',
      }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="withdraw-modal-title"
    >
      <div
        className="bm-modal-scale"
        style={{
          width: '100%',
          maxWidth: '500px',
          backgroundColor: PRECISION_SURFACES.panel,
          border: `1px solid ${PRECISION_COLORS.borderSubtle}`,
          borderRadius: '8px',
          padding: '28px 24px',
          boxSizing: 'border-box',
          position: 'relative',
          color: PRECISION_COLORS.textPrimary,
          fontFamily: "'Geist', sans-serif",
          boxShadow: '0 20px 48px rgba(0, 0, 0, 0.6)',
        }}
      >
        {/* Botão Fechar X */}
        <button
          type="button"
          onClick={handleClose}
          style={{
            position: 'absolute',
            top: '18px',
            right: '18px',
            background: 'none',
            border: 'none',
            color: PRECISION_COLORS.textSecondary,
            fontSize: '18px',
            cursor: 'pointer',
            padding: '4px',
            lineHeight: 1,
          }}
          aria-label="Cerrar retiro"
        >
          ✕
        </button>

        <h2
          id="withdraw-modal-title"
          style={{
            margin: '0 0 16px',
            fontSize: '22px',
            fontWeight: 800,
            color: PRECISION_COLORS.textPrimary,
            letterSpacing: '-0.01em',
          }}
        >
          Retirar fondos
        </h2>
        <p style={{ fontSize: '12px', lineHeight: 1.5 }}>{es.withdraw_demo.notice}</p>

        {success ? (
          /* ESTADO SUCESSO: SÓBRIO, CONFIRMAÇÃO DIRETA SEM CONFETES */
          <div data-testid="withdraw-success-state" style={{ textAlign: 'center', padding: '16px 8px' }}>
            <div
              style={{
                width: '52px',
